const packed={"format":"own-undefined-v1","undefinedPaths":[],"value":{"powerclean":{"id":"powerclean","edits":{"cz":"Přemístění do podřepu ze země","en":"Power Clean from the Floor","eq":["cinka","prostor"],"foc":["Zrychlení činky a kontrolovaný příjem na ramena v podřepu.","Accelerate the bar and receive it on the shoulders in a partial squat."],"pos":["Činka leží na pevné ploše blízko holení. Chodidla jsou přibližně pod boky, ruce nadhmatem vně nohou, paže dlouhé a trup zpevněný. Zvol hmotnost, se kterou ovládáš i odložení.","Place the bar on a firm surface close to the shins. Set the feet roughly under the hips, grip outside the legs, keep the arms long and brace the trunk. Choose a load you can also lower reliably."],"exe":["Odlep činku tlakem nohou do podlahy a veď ji blízko těla. Nad koleny zrychli propnutím nohou a kyčlí. Podsuň se, otoč lokty vpřed a přijmi osu na přední ramena v podřepu nad vodorovnou polohou stehen. Ustal se a vstaň. Po kontrolovaném návratu na zem znovu nastav start.","Drive through the floor and keep the bar close. Above the knees, accelerate by extending the legs and hips. Move underneath, turn the elbows forward and receive the bar on the front shoulders with the thighs above horizontal. Stabilize and stand. Lower under control to the floor and reset."],"wat":["Osu nenabírej bicepsovým zdvihem ani nechytáš jen do rukou. Při učení pracuj s trenérem, včetně příjmu a odložení. Při bolesti, ztrátě rovnováhy nebo nekontrolovaném pádu činky sérii ukonči.","Do not curl the bar or receive it only in the hands. Learn with a coach, including the catch and lowering. End the set for pain, loss of balance or an uncontrolled falling bar."],"pro":["Začni nácvikem jednotlivých částí s lehkou osou. Výtah bez zachycení nebo příjem z visu jsou jiné úkoly; nejsou povinnou řadou. Zátěž měň podle techniky, ne automaticky po dosažení počtu opakování.","Begin with light-bar practice of individual phases. A pull without a catch and a clean from the hang are different tasks, not a required ladder. Change load according to technique rather than automatically after a repetition target."],"equipmentDetail":["Velká činka a volná plocha pro zvednutí i odložení. Počítej dokončená přemístění; zapisuj celkovou hmotnost osy a kotoučů. Historické zápisy se nepřepočítávají.","A barbell and clear space for lifting and lowering. Count completed cleans and record the total bar-and-plate mass. Historical entries are not recalculated."],"source":{"author":"National Strength and Conditioning Association","document":"Integration of Clean Variations, Progressions, and Application in Strength and Conditioning Programs (2023)","url":"https://www.nsca.com/contentassets/d29cb11c8dd84c209dd8377fb3c71b3d/nsca-coach-10.1.1-integration-of-clean-variations-progressions-and-application.pdf"}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":["shoulders","back","trunk"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["prostor"]],"aliases":["Přemístění","Power Clean"]},"policy":{"id":"powerclean","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-lift-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"powerclean","atlasId":"powerclean","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d45d9e1cdc78aef7671f3e18a3fbf0dd2f1d219c2fcef4b8e8e32e2e446bf5e8","thumb":"/unified-atlas/powerclean-60032c305f04ca7e-thumb.webp","detail":"/unified-atlas/powerclean-8163a39d8595484b-detail.webp","inkThumb":"/unified-atlas/powerclean-67761807f1dba90e-inkThumb.webp","inkDetail":"/unified-atlas/powerclean-38c70d486cf662ea-inkDetail.webp","fillThumb":"/unified-atlas/powerclean-23bd44973080a228-fillThumb.webp","fillDetail":"/unified-atlas/powerclean-df98a8184b6a1099-fillDetail.webp"},"sourceSha256":"d45d9e1cdc78aef7671f3e18a3fbf0dd2f1d219c2fcef4b8e8e32e2e446bf5e8","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka a volný prostor pro zvednutí a odložení","Barbell and clear space for lifting and lowering"],"libraryOrders":{"weightlifting":9},"deliveryProfiles":{"4518f2cf58f35122":{"fields":{"id":"powerclean","cz":"Přemístění do podřepu ze země","en":"Power Clean from the Floor","pat":"prenos","eq":["cinka","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":180,"unilateral":false,"sideMode":"none","focus":["Zrychlení činky a kontrolovaný příjem na ramena v podřepu.","Accelerate the bar and receive it on the shoulders in a partial squat."],"startPosition":["Činka leží na pevné ploše blízko holení. Chodidla jsou přibližně pod boky, ruce nadhmatem vně nohou, paže dlouhé a trup zpevněný. Zvol hmotnost, se kterou ovládáš i odložení.","Place the bar on a firm surface close to the shins. Set the feet roughly under the hips, grip outside the legs, keep the arms long and brace the trunk. Choose a load you can also lower reliably."],"execution":["Odlep činku tlakem nohou do podlahy a veď ji blízko těla. Nad koleny zrychli propnutím nohou a kyčlí. Podsuň se, otoč lokty vpřed a přijmi osu na přední ramena v podřepu nad vodorovnou polohou stehen. Ustal se a vstaň. Po kontrolovaném návratu na zem znovu nastav start.","Drive through the floor and keep the bar close. Above the knees, accelerate by extending the legs and hips. Move underneath, turn the elbows forward and receive the bar on the front shoulders with the thighs above horizontal. Stabilize and stand. Lower under control to the floor and reset."],"watchFor":["Osu nenabírej bicepsovým zdvihem ani nechytáš jen do rukou. Při učení pracuj s trenérem, včetně příjmu a odložení. Při bolesti, ztrátě rovnováhy nebo nekontrolovaném pádu činky sérii ukonči.","Do not curl the bar or receive it only in the hands. Learn with a coach, including the catch and lowering. End the set for pain, loss of balance or an uncontrolled falling bar."]},"progression":["Začni nácvikem jednotlivých částí s lehkou osou. Výtah bez zachycení nebo příjem z visu jsou jiné úkoly; nejsou povinnou řadou. Zátěž měň podle techniky, ne automaticky po dosažení počtu opakování.","Begin with light-bar practice of individual phases. A pull without a catch and a clean from the hang are different tasks, not a required ladder. Change load according to technique rather than automatically after a repetition target."]}}},"ex26_clean_pull":{"id":"ex26_clean_pull","edits":{"cz":"Výtah na přemístění bez zachycení","en":"Clean Pull","eq":["cinka","prostor"],"hd":null,"foc":["Zrychlení činky nohama a kyčlemi bez příjmu na ramena.","Accelerate the bar with the legs and hips without receiving it on the shoulders."],"pos":["Nastav start přemístění ze země: činka blízko holení, ruce vně nohou, paže dlouhé a trup zpevněný. Stůj na pevné ploše s místem pro odložení.","Set up as for a clean from the floor: bar close to the shins, hands outside the legs, arms long and trunk braced. Use a firm surface with room for lowering."],"exe":["Tlakem nohou zvedej činku podél těla. Nad koleny zrychli současným dokončením propnutí nohou a kyčlí; ramena přirozeně vystoupají. Nepodsedej pro zachycení a neotáčej osu do předního držení. Vrať činku na zem pod kontrolou a znovu nastav start. Jeden celý tah je jedno opakování.","Push with the legs to lift the bar close to the body. Above the knees accelerate by finishing leg and hip extension; the shoulders rise naturally. Do not move underneath to catch or turn the bar into the front rack. Lower under control to the floor and reset. One complete pull counts as one repetition."],"wat":["Činka nemá obíhat tělo vpřed a nejde o pomalý přítah lokty k bradě. Paže nezahajují pohyb. Nácvik načasování a zvolenou zátěž posuď s trenérem; při ztrátě dráhy nebo bolesti přestaň.","Do not swing the bar forward or turn this into a slow upright row. The arms do not initiate the lift. Review timing and load with a coach; stop for loss of bar-path control or pain."],"pro":["Nejprve lehká osa a opakovatelná dráha. Přemístění přidává samostatnou dovednost příjmu; není automatickou progresí výtahu. Zátěž nezvyšuj za cenu pomalého nebo nekontrolovaného dokončení.","First use a light bar and repeatable path. A clean adds the separate receiving skill and is not an automatic progression. Do not increase load at the expense of a slow or uncontrolled finish."],"equipmentDetail":["Velká činka a volná plocha. Zapisuj celkovou hmotnost osy a kotoučů a počet tahů, nikoli výšku činky nebo skoky. Původní hmotnosti zůstávají beze změny.","A barbell and clear space. Record total bar-and-plate mass and the number of pulls, not bar height or jumps. Existing weight entries remain unchanged."],"source":{"author":"Greg Everett / Catalyst Athletics","document":"Clean Pull — Olympic Weightlifting Exercise Library","url":"https://catalystathletics.com/exercise/98/Clean-Pull/"}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":["back","lower_legs","trunk"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["prostor"]],"aliases":["Výtah na přemístění"]},"policy":{"id":"ex26_clean_pull","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-lift-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_clean_pull","atlasId":"ex26_clean_pull","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5bd4df8086577b01645d5855309075559c606fb6e83288a1bd9461db048848d6","thumb":"/expansion-atlas/ex26_clean_pull-original-256.webp","detail":"/expansion-atlas/ex26_clean_pull-original-960.webp","inkThumb":"/expansion-atlas/ex26_clean_pull-ink-256.webp","inkDetail":"/expansion-atlas/ex26_clean_pull-ink-960.webp","fillThumb":"/expansion-atlas/ex26_clean_pull-fill-256.webp","fillDetail":"/expansion-atlas/ex26_clean_pull-fill-960.webp"},"sourceSha256":"5bd4df8086577b01645d5855309075559c606fb6e83288a1bd9461db048848d6","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka a volný prostor pro zvednutí a odložení","Barbell and clear space for lifting and lowering"],"libraryOrders":{"weightlifting":8},"deliveryProfiles":{"495807ecd8a0695c":{"fields":{"id":"ex26_clean_pull","cz":"Výtah na přemístění bez zachycení","en":"Clean Pull","pat":"ohyb","eq":["cinka","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Zrychlení činky nohama a kyčlemi bez příjmu na ramena.","Accelerate the bar with the legs and hips without receiving it on the shoulders."],"startPosition":["Nastav start přemístění ze země: činka blízko holení, ruce vně nohou, paže dlouhé a trup zpevněný. Stůj na pevné ploše s místem pro odložení.","Set up as for a clean from the floor: bar close to the shins, hands outside the legs, arms long and trunk braced. Use a firm surface with room for lowering."],"execution":["Tlakem nohou zvedej činku podél těla. Nad koleny zrychli současným dokončením propnutí nohou a kyčlí; ramena přirozeně vystoupají. Nepodsedej pro zachycení a neotáčej osu do předního držení. Vrať činku na zem pod kontrolou a znovu nastav start. Jeden celý tah je jedno opakování.","Push with the legs to lift the bar close to the body. Above the knees accelerate by finishing leg and hip extension; the shoulders rise naturally. Do not move underneath to catch or turn the bar into the front rack. Lower under control to the floor and reset. One complete pull counts as one repetition."],"watchFor":["Činka nemá obíhat tělo vpřed a nejde o pomalý přítah lokty k bradě. Paže nezahajují pohyb. Nácvik načasování a zvolenou zátěž posuď s trenérem; při ztrátě dráhy nebo bolesti přestaň.","Do not swing the bar forward or turn this into a slow upright row. The arms do not initiate the lift. Review timing and load with a coach; stop for loss of bar-path control or pain."]},"progression":["Nejprve lehká osa a opakovatelná dráha. Přemístění přidává samostatnou dovednost příjmu; není automatickou progresí výtahu. Zátěž nezvyšuj za cenu pomalého nebo nekontrolovaného dokončení.","First use a light bar and repeatable path. A clean adds the separate receiving skill and is not an automatic progression. Do not increase load at the expense of a slow or uncontrolled finish."]}}},"ex26_hang_clean":{"id":"ex26_hang_clean","edits":{"cz":"Přemístění z visu do dřepu","en":"Hang Squat Clean","eq":["cinka","prostor"],"foc":["Přemístění z visu nad koleny s kontrolovaným příjmem do předního dřepu.","A clean from an above-knee hang with a controlled front-squat receive."],"pos":["Nejprve zvedni činku do stoje. Drž ji nadhmatem vně stehen, trup zpevněný. Pokrčením kyčlí a kolen spusť osu těsně nad kolena. Pro tuto variantu už potřebuješ ovládat přední držení a dřep.","First lift the bar to standing. Grip outside the thighs and brace the trunk. Bend the hips and knees to lower the bar just above the knees. This variation requires control of the front rack and front squat."],"exe":["Z visu zrychli činku tlakem nohou a propnutím kyčlí. Přesuň se pod osu, otoč lokty vpřed a přijmi ji na přední ramena do dřepu. Vstaň s osou pod kontrolou. Vrať ji do visu; po posledním opakování ji odlož. Jeden příjem a úplné postavení je jedno opakování.","From the hang, accelerate with leg drive and hip extension. Move under the bar, turn the elbows forward and receive it on the front shoulders in a squat. Stand with control. Return to the hang; lower to the floor after the final repetition. One receive and full stand counts as one repetition."],"wat":["Nejde o hang power clean s mělkým příjmem. Hloubku nezískávej ztrátou opory chodidel nebo zhroucením trupu. Nácvik příjmu a návratu veď s trenérem; pokud dřep či přední držení bolí nebo není kontrolované, zvol jiný úkol.","This is not a hang power clean with a shallow receive. Do not gain depth by losing foot support or collapsing the trunk. Learn the catch and return with a coach; choose another task if the squat or front rack is painful or uncontrolled."],"pro":["Začni lehkou osou a samostatným nácvikem předního držení, dřepu a načasování. Vyšší hmotnost ani hlubší příjem nejsou povinným dalším krokem. Jinou výšku visu eviduj jako vlastní variantu.","Start with a light bar and separate practice of the rack, squat and timing. More load or greater depth is not a required next step. Record another hang height as a personal variation."],"equipmentDetail":["Velká činka a volná plocha pro návrat i odložení. Zapisuj celkovou hmotnost osy a kotoučů a počet celých přemístění. Starší neurčenou hloubku ani zapsaná kila neodhadujeme.","A barbell and clear space for returning and lowering. Record total bar-and-plate mass and complete cleans. Earlier unspecified depth and recorded kilograms are not inferred."],"source":{"author":"American Council on Exercise","document":"Hang Clean — Full Body/Integrated Exercises","url":"https://www.acefitness.org/resources/everyone/exercise-library/312/hang-clean/"}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":["shoulders","back","trunk"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["prostor"]],"aliases":["Přemístění z visu","Hang Clean"]},"policy":{"id":"ex26_hang_clean","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-lift-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_hang_clean","atlasId":"ex26_hang_clean","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ba4b2490686b3f5d74a15d17bf973b36c7b032b6164fa71cf74f7ba643560e0a","thumb":"/expansion-atlas/ex26_hang_clean-original-256.webp","detail":"/expansion-atlas/ex26_hang_clean-original-960.webp","inkThumb":"/expansion-atlas/ex26_hang_clean-ink-256.webp","inkDetail":"/expansion-atlas/ex26_hang_clean-ink-960.webp","fillThumb":"/expansion-atlas/ex26_hang_clean-fill-256.webp","fillDetail":"/expansion-atlas/ex26_hang_clean-fill-960.webp"},"sourceSha256":"ba4b2490686b3f5d74a15d17bf973b36c7b032b6164fa71cf74f7ba643560e0a","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka a volný prostor pro zvednutí a odložení","Barbell and clear space for lifting and lowering"],"libraryOrders":{"weightlifting":10},"deliveryProfiles":{"eba47d5806d99be5":{"fields":{"id":"ex26_hang_clean","cz":"Přemístění z visu do dřepu","en":"Hang Squat Clean","pat":"ohyb","eq":["cinka","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Přemístění z visu nad koleny s kontrolovaným příjmem do předního dřepu.","A clean from an above-knee hang with a controlled front-squat receive."],"startPosition":["Nejprve zvedni činku do stoje. Drž ji nadhmatem vně stehen, trup zpevněný. Pokrčením kyčlí a kolen spusť osu těsně nad kolena. Pro tuto variantu už potřebuješ ovládat přední držení a dřep.","First lift the bar to standing. Grip outside the thighs and brace the trunk. Bend the hips and knees to lower the bar just above the knees. This variation requires control of the front rack and front squat."],"execution":["Z visu zrychli činku tlakem nohou a propnutím kyčlí. Přesuň se pod osu, otoč lokty vpřed a přijmi ji na přední ramena do dřepu. Vstaň s osou pod kontrolou. Vrať ji do visu; po posledním opakování ji odlož. Jeden příjem a úplné postavení je jedno opakování.","From the hang, accelerate with leg drive and hip extension. Move under the bar, turn the elbows forward and receive it on the front shoulders in a squat. Stand with control. Return to the hang; lower to the floor after the final repetition. One receive and full stand counts as one repetition."],"watchFor":["Nejde o hang power clean s mělkým příjmem. Hloubku nezískávej ztrátou opory chodidel nebo zhroucením trupu. Nácvik příjmu a návratu veď s trenérem; pokud dřep či přední držení bolí nebo není kontrolované, zvol jiný úkol.","This is not a hang power clean with a shallow receive. Do not gain depth by losing foot support or collapsing the trunk. Learn the catch and return with a coach; choose another task if the squat or front rack is painful or uncontrolled."]},"progression":["Začni lehkou osou a samostatným nácvikem předního držení, dřepu a načasování. Vyšší hmotnost ani hlubší příjem nejsou povinným dalším krokem. Jinou výšku visu eviduj jako vlastní variantu.","Start with a light bar and separate practice of the rack, squat and timing. More load or greater depth is not a required next step. Record another hang height as a personal variation."]}}},"ex26_hang_snatch":{"id":"ex26_hang_snatch","edits":{"cz":"Trh velké činky z visu do dřepu","en":"Hang Squat Snatch","eq":["cinka","weightlifting_area"],"foc":["Trh z visu nad koleny s příjmem na napnuté paže v dřepu.","Snatch from an above-knee hang into a squat with the bar on straight arms."],"pos":["Zvedni lehkou osu do stoje širokým trhovým úchopem. Zpevni trup a pokrčením kyčlí a kolen ji spusť těsně nad kolena. Připrav vhodnou plochu pro odložení a předem s trenérem nacvič návrat i přerušení nepovedeného pokusu.","Lift a light bar to standing with a wide snatch grip. Brace the trunk and bend the hips and knees to lower it just above the knees. Prepare an appropriate unloading area and first practise the return and an unsuccessful attempt with a coach."],"exe":["Z visu zrychli osu tlakem nohou a propnutím kyčlí. Přesuň se pod ni a přijmi ji nad hlavou na napnuté paže v dřepu. Po ustálení se úplně postav. Nacvičeným způsobem vrať osu do visu, nebo ji odlož a připrav nový start. Jeden příjem a postavení je jedno opakování.","Accelerate from the hang with leg drive and hip extension. Move underneath and receive the bar overhead on straight arms in a squat. Stabilize, then stand fully. Use the practised return to the hang or lower and prepare a new start. One receive and stand counts as one repetition."],"wat":["Osu neveď širokým obloukem a příjem nenahrazuj dotlačením. Hloubku nevynucuj ztrátou opory chodidel nebo kontroly ramen. Pokud neovládáš dřep s osou nad hlavou a její odložení, zůstaň u průpravy s trenérem. Při bolesti nebo nekontrolovaném pohybu skonči.","Avoid looping the bar outward or pressing it out to complete the catch. Do not force depth by losing foot support or shoulder control. If the overhead squat and unloading are not controlled, stay with coached preparatory drills. Stop for pain or uncontrolled movement."],"pro":["Průprava s tyčí je samostatný lehčí úkol. Vyšší či nižší vis, mělký power příjem a zátěž mění zadání; nejsou automatickou řadou. Nejdřív upevni konkrétní provedení a návrat, teprve pak s trenérem posuď další změnu.","Dowel practice is a separate easier task. A different hang height, shallow power receive and load change the assignment; they are not an automatic ladder. Establish the specific execution and return before considering a change with the coach."],"equipmentDetail":["Velká činka a plocha určená pro vzpírání i odložení činky, s volným okolím a výškou nad hlavou. Zapisuj celkovou hmotnost osy a kotoučů a celé trhy. Staré kg a neurčené výšky visu zůstávají bez výkladu.","A barbell and an area suitable for lifting and unloading it, with clear surroundings and overhead clearance. Record total bar-and-plate mass and complete snatches. Earlier kilograms and unspecified hang heights remain uninterpreted."],"source":{"author":"Greg Everett / Catalyst Athletics","document":"Hang Snatch (Hang Squat Snatch)","url":"https://catalystathletics.com/exercise/63/Hang-Snatch/"}},"taxonomy":{"regions":["hips","thighs","shoulders"],"secondaryRegions":["back","trunk"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["weightlifting_area"]],"aliases":["Trh z visu","Hang Snatch"]},"policy":{"id":"ex26_hang_snatch","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["weightlifting_area"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-lift-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_hang_snatch","atlasId":"ex26_hang_snatch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"e1df4affd0f6488d70a6b14e94e99c399631e2eddaa4afe4d2378d36b271e1af","thumb":"/expansion-atlas/ex26_hang_snatch-original-256.webp","detail":"/expansion-atlas/ex26_hang_snatch-original-960.webp","inkThumb":"/expansion-atlas/ex26_hang_snatch-ink-256.webp","inkDetail":"/expansion-atlas/ex26_hang_snatch-ink-960.webp","fillThumb":"/expansion-atlas/ex26_hang_snatch-fill-256.webp","fillDetail":"/expansion-atlas/ex26_hang_snatch-fill-960.webp"},"sourceSha256":"e1df4affd0f6488d70a6b14e94e99c399631e2eddaa4afe4d2378d36b271e1af","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka; plocha pro vzpírání a odložení s volným okolím a výškou nad hlavou","Barbell; suitable weightlifting and unloading area with clear surroundings and overhead clearance"],"libraryOrders":{"weightlifting":14},"deliveryProfiles":{"15bb47422bb6cd70":{"fields":{"id":"ex26_hang_snatch","cz":"Trh velké činky z visu do dřepu","en":"Hang Squat Snatch","pat":"ohyb","eq":["cinka","weightlifting_area"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Trh z visu nad koleny s příjmem na napnuté paže v dřepu.","Snatch from an above-knee hang into a squat with the bar on straight arms."],"startPosition":["Zvedni lehkou osu do stoje širokým trhovým úchopem. Zpevni trup a pokrčením kyčlí a kolen ji spusť těsně nad kolena. Připrav vhodnou plochu pro odložení a předem s trenérem nacvič návrat i přerušení nepovedeného pokusu.","Lift a light bar to standing with a wide snatch grip. Brace the trunk and bend the hips and knees to lower it just above the knees. Prepare an appropriate unloading area and first practise the return and an unsuccessful attempt with a coach."],"execution":["Z visu zrychli osu tlakem nohou a propnutím kyčlí. Přesuň se pod ni a přijmi ji nad hlavou na napnuté paže v dřepu. Po ustálení se úplně postav. Nacvičeným způsobem vrať osu do visu, nebo ji odlož a připrav nový start. Jeden příjem a postavení je jedno opakování.","Accelerate from the hang with leg drive and hip extension. Move underneath and receive the bar overhead on straight arms in a squat. Stabilize, then stand fully. Use the practised return to the hang or lower and prepare a new start. One receive and stand counts as one repetition."],"watchFor":["Osu neveď širokým obloukem a příjem nenahrazuj dotlačením. Hloubku nevynucuj ztrátou opory chodidel nebo kontroly ramen. Pokud neovládáš dřep s osou nad hlavou a její odložení, zůstaň u průpravy s trenérem. Při bolesti nebo nekontrolovaném pohybu skonči.","Avoid looping the bar outward or pressing it out to complete the catch. Do not force depth by losing foot support or shoulder control. If the overhead squat and unloading are not controlled, stay with coached preparatory drills. Stop for pain or uncontrolled movement."]},"progression":["Průprava s tyčí je samostatný lehčí úkol. Vyšší či nižší vis, mělký power příjem a zátěž mění zadání; nejsou automatickou řadou. Nejdřív upevni konkrétní provedení a návrat, teprve pak s trenérem posuď další změnu.","Dowel practice is a separate easier task. A different hang height, shallow power receive and load change the assignment; they are not an automatic ladder. Establish the specific execution and return before considering a change with the coach."]}}},"ex26_barbell_snatch":{"id":"ex26_barbell_snatch","edits":{"cz":"Trh velké činky ze země do dřepu","en":"Squat Snatch from the Floor","eq":["cinka","weightlifting_area"],"foc":["Plynulé spojení tahu ze země, zrychlení a příjmu činky v dřepu nad hlavou.","Link the floor pull, acceleration and an overhead squat receive."],"pos":["Postav se k ose na ploše určené pro vzpírání. Nastav široký trhový úchop, osu blízko holení a zpevněný start s oporou obou chodidel. Volný prostor musí umožnit i odložení; návrat a přerušení pokusu nacvič předem s trenérem.","Set up at the bar in an area suitable for weightlifting. Use a wide snatch grip, keep the bar close to the shins and brace with support through both feet. Leave enough space for unloading; first practise returning and aborting the lift with a coach."],"exe":["Tlakem nohou zvedej osu blízko těla. Po průchodu koleny zrychli propnutím nohou a kyčlí. Přesuň se pod osu, přijmi ji na napnuté paže nad hlavou v dřepu a ustal ji. Úplně se postav, potom ji nacvičeným způsobem odlož. Další tah začíná znovu ze země.","Push through the floor and keep the bar close. After passing the knees, accelerate with leg and hip extension. Move underneath, receive overhead on straight arms in a squat and stabilize. Stand fully, then unload using the practised method. Start the next pull from the floor again."],"wat":["Nejde o tlak nad hlavu ani o trh do mělkého podřepu. Činka nemá obíhat tělo a ramena či záda nemají nahrazovat chybějící kontrolu příjmu. Bez jistého dřepu nad hlavou a nacvičeného odložení zvol průpravu s trenérem. Při bolesti nebo ztrátě kontroly pokus přeruš.","This is neither an overhead press nor a shallow power snatch. Do not loop the bar around the body or compensate through the shoulders or back for an uncontrolled receive. Without a controlled overhead squat and practised unloading, choose coached preparation. Stop the attempt for pain or loss of control."],"pro":["Trh z visu může oddělit nácvik zrychlení a příjmu, ale nenahrazuje výuku tahu ze země. Zátěž se nezvyšuje jen proto, že jsi splnil počet opakování. Udrž stejný úkol; jiné starty nebo hloubky poznamenej jako variantu.","A hang snatch can isolate acceleration and receiving practice but does not replace learning the floor pull. Do not add load merely because the repetition target was met. Keep the task consistent and note different starts or depths as a variation."],"equipmentDetail":["Velká činka a vhodná vzpěračská plocha, dostatečná výška a prostor pro odložení. Jedno opakování zahrnuje tah, příjem a postavení. Hmotnost je celá osa s kotouči; uložené dávky a hmotnosti se nepřepočítávají.","A barbell and suitable weightlifting area, with sufficient height and unloading space. One repetition includes the pull, receive and stand. Weight means the complete bar and plates; stored doses and weights are not recalculated."],"source":{"author":"American Council on Exercise","document":"Snatch — Full Body/Integrated Exercises","url":"https://www.acefitness.org/resources/everyone/exercise-library/314/snatch/"}},"taxonomy":{"regions":["hips","thighs","shoulders"],"secondaryRegions":["back","trunk"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["weightlifting_area"]],"aliases":["Trh velké činky ze země","Barbell Snatch from Floor"]},"policy":{"id":"ex26_barbell_snatch","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["weightlifting_area"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-lift-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_barbell_snatch","atlasId":"ex26_barbell_snatch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d1e2242cb5121c0fb9d31a6489546102fdfbed20ba712de635b013b74a15d56b","thumb":"/expansion-atlas/ex26_barbell_snatch-original-256.webp","detail":"/expansion-atlas/ex26_barbell_snatch-original-960.webp","inkThumb":"/expansion-atlas/ex26_barbell_snatch-ink-256.webp","inkDetail":"/expansion-atlas/ex26_barbell_snatch-ink-960.webp","fillThumb":"/expansion-atlas/ex26_barbell_snatch-fill-256.webp","fillDetail":"/expansion-atlas/ex26_barbell_snatch-fill-960.webp"},"sourceSha256":"d1e2242cb5121c0fb9d31a6489546102fdfbed20ba712de635b013b74a15d56b","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka; plocha pro vzpírání a odložení s volným okolím a výškou nad hlavou","Barbell; suitable weightlifting and unloading area with clear surroundings and overhead clearance"],"libraryOrders":{"weightlifting":15},"deliveryProfiles":{"53d7e2b9e7436d8d":{"fields":{"id":"ex26_barbell_snatch","cz":"Trh velké činky ze země do dřepu","en":"Squat Snatch from the Floor","pat":"ohyb","eq":["cinka","weightlifting_area"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Plynulé spojení tahu ze země, zrychlení a příjmu činky v dřepu nad hlavou.","Link the floor pull, acceleration and an overhead squat receive."],"startPosition":["Postav se k ose na ploše určené pro vzpírání. Nastav široký trhový úchop, osu blízko holení a zpevněný start s oporou obou chodidel. Volný prostor musí umožnit i odložení; návrat a přerušení pokusu nacvič předem s trenérem.","Set up at the bar in an area suitable for weightlifting. Use a wide snatch grip, keep the bar close to the shins and brace with support through both feet. Leave enough space for unloading; first practise returning and aborting the lift with a coach."],"execution":["Tlakem nohou zvedej osu blízko těla. Po průchodu koleny zrychli propnutím nohou a kyčlí. Přesuň se pod osu, přijmi ji na napnuté paže nad hlavou v dřepu a ustal ji. Úplně se postav, potom ji nacvičeným způsobem odlož. Další tah začíná znovu ze země.","Push through the floor and keep the bar close. After passing the knees, accelerate with leg and hip extension. Move underneath, receive overhead on straight arms in a squat and stabilize. Stand fully, then unload using the practised method. Start the next pull from the floor again."],"watchFor":["Nejde o tlak nad hlavu ani o trh do mělkého podřepu. Činka nemá obíhat tělo a ramena či záda nemají nahrazovat chybějící kontrolu příjmu. Bez jistého dřepu nad hlavou a nacvičeného odložení zvol průpravu s trenérem. Při bolesti nebo ztrátě kontroly pokus přeruš.","This is neither an overhead press nor a shallow power snatch. Do not loop the bar around the body or compensate through the shoulders or back for an uncontrolled receive. Without a controlled overhead squat and practised unloading, choose coached preparation. Stop the attempt for pain or loss of control."]},"progression":["Trh z visu může oddělit nácvik zrychlení a příjmu, ale nenahrazuje výuku tahu ze země. Zátěž se nezvyšuje jen proto, že jsi splnil počet opakování. Udrž stejný úkol; jiné starty nebo hloubky poznamenej jako variantu.","A hang snatch can isolate acceleration and receiving practice but does not replace learning the floor pull. Do not add load merely because the repetition target was met. Keep the task consistent and note different starts or depths as a variation."]}}},"ex26_clean_jerk":{"id":"ex26_clean_jerk","edits":{"cz":"Nadhoz s výrazem do střihu","en":"Clean and Split Jerk","eq":["cinka","weightlifting_area"],"foc":["Přemístění ze země na ramena, ustálení a navazující výraz do střihu.","A floor clean to the shoulders, stabilization and a following split jerk."],"pos":["Připrav lehkou osu, vhodnou plochu a volné okolí i výšku nad hlavou. Nastav zpevněný start ze země s úchopem vně nohou. Příjem, střih, návrat a přerušení nezdařeného pokusu nejprve nacvič s trenérem.","Prepare a light bar, suitable floor area and clear surroundings and overhead space. Set a braced floor start with the hands outside the legs. First practise receiving, splitting, returning and aborting an attempt with a coach."],"exe":["Přemísti osu na přední stranu ramen a úplně se postav. Znovu se připrav; krátkým svislým podřepem a odrazem nohou vyšleš osu vzhůru. Přijmi ji na napnuté paže ve střihu a ustal. Přední chodidlo přisuň část cesty zpět, potom zadní dopředu do stoje. Odlož osu nacvičeným způsobem; další celý nadhoz začíná ze země.","Clean the bar onto the front shoulders and stand fully. Reset, then use a short vertical dip and leg drive. Receive on straight arms in a split and stabilize. Recover the front foot partway back, then the rear foot forward to standing. Lower the bar by the practised method; the next complete lift starts from the floor."],"wat":["Ve střihu opři přední chodidlo, zadní patu nech zvednutou a zadní koleno měkké. Nohy nemusí být na jedné úzké čáře. Činku ustal před sbíráním nohou; při ztrátě kontroly nepokračuj. Hloubka příjmu při přemístění je samostatně zvolená varianta, kterou nelze odvodit z obrázku výrazu.","Support the front foot, keep the rear heel raised and the rear knee soft. Avoid a tightrope stance. Stabilize the bar before recovering the feet; stop if control is lost. Clean receiving depth is a separately chosen variation and cannot be inferred from the jerk illustration."],"pro":["Oddělený nácvik přemístění a výrazu usnadní kontrolu jednotlivých částí. Zátěž i spojení částí vol s trenérem podle zvládnuté techniky; samotný počet opakování není pokyn k přidání hmotnosti.","Separate clean and jerk practice allows each part to be checked. Choose load and combination with the coach according to technique; repetition count alone does not justify increasing weight."],"equipmentDetail":["Velká činka a vhodná plocha pro její zvedání a odložení. Jedno opakování zde znamená celé přemístění a jeden výraz, ne dvě opakování. Zapisuj hmotnost celé osy s kotouči; uložené počty, kg a neurčenou hloubku příjmu nepřepočítáváme.","A barbell and an area suitable for lifting and lowering it. Here one repetition means one clean plus one jerk, not two repetitions. Record total bar-and-plate mass; stored repetitions, kilograms and unspecified receiving depth are not converted."],"source":{"author":"International Weightlifting Federation; Greg Everett / Catalyst Athletics","document":"Clean & Jerk — two consecutive movements; Split Jerk","url":"https://iwf.sport/2025/04/23/iwf120y-72-2025-knowing-one-of-the-basic-lifts-clean-jerk/"}},"taxonomy":{"regions":["hips","thighs","shoulders"],"secondaryRegions":["trunk","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["weightlifting_area"]],"aliases":["Nadhoz","Clean and Jerk"]},"policy":{"id":"ex26_clean_jerk","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["weightlifting_area"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-clean-plus-one-jerk-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_clean_jerk","atlasId":"ex26_clean_jerk","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"cb07e660768224ec68f0e97febd905f3c9dbbefe3e80d03e8789bd542af46a2b","thumb":"/expansion-atlas/ex26_clean_jerk-original-256.webp","detail":"/expansion-atlas/ex26_clean_jerk-original-960.webp","inkThumb":"/expansion-atlas/ex26_clean_jerk-ink-256.webp","inkDetail":"/expansion-atlas/ex26_clean_jerk-ink-960.webp","fillThumb":"/expansion-atlas/ex26_clean_jerk-fill-256.webp","fillDetail":"/expansion-atlas/ex26_clean_jerk-fill-960.webp"},"sourceSha256":"cb07e660768224ec68f0e97febd905f3c9dbbefe3e80d03e8789bd542af46a2b","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka; plocha pro zvedání a odložení s volným okolím a výškou","Barbell; suitable lifting and lowering area with surrounding and overhead clearance"],"libraryOrders":{"weightlifting":12},"deliveryProfiles":{"988a318d2b05ff70":{"fields":{"id":"ex26_clean_jerk","cz":"Nadhoz s výrazem do střihu","en":"Clean and Split Jerk","pat":"ohyb","eq":["cinka","weightlifting_area"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Přemístění ze země na ramena, ustálení a navazující výraz do střihu.","A floor clean to the shoulders, stabilization and a following split jerk."],"startPosition":["Připrav lehkou osu, vhodnou plochu a volné okolí i výšku nad hlavou. Nastav zpevněný start ze země s úchopem vně nohou. Příjem, střih, návrat a přerušení nezdařeného pokusu nejprve nacvič s trenérem.","Prepare a light bar, suitable floor area and clear surroundings and overhead space. Set a braced floor start with the hands outside the legs. First practise receiving, splitting, returning and aborting an attempt with a coach."],"execution":["Přemísti osu na přední stranu ramen a úplně se postav. Znovu se připrav; krátkým svislým podřepem a odrazem nohou vyšleš osu vzhůru. Přijmi ji na napnuté paže ve střihu a ustal. Přední chodidlo přisuň část cesty zpět, potom zadní dopředu do stoje. Odlož osu nacvičeným způsobem; další celý nadhoz začíná ze země.","Clean the bar onto the front shoulders and stand fully. Reset, then use a short vertical dip and leg drive. Receive on straight arms in a split and stabilize. Recover the front foot partway back, then the rear foot forward to standing. Lower the bar by the practised method; the next complete lift starts from the floor."],"watchFor":["Ve střihu opři přední chodidlo, zadní patu nech zvednutou a zadní koleno měkké. Nohy nemusí být na jedné úzké čáře. Činku ustal před sbíráním nohou; při ztrátě kontroly nepokračuj. Hloubka příjmu při přemístění je samostatně zvolená varianta, kterou nelze odvodit z obrázku výrazu.","Support the front foot, keep the rear heel raised and the rear knee soft. Avoid a tightrope stance. Stabilize the bar before recovering the feet; stop if control is lost. Clean receiving depth is a separately chosen variation and cannot be inferred from the jerk illustration."]},"progression":["Oddělený nácvik přemístění a výrazu usnadní kontrolu jednotlivých částí. Zátěž i spojení částí vol s trenérem podle zvládnuté techniky; samotný počet opakování není pokyn k přidání hmotnosti.","Separate clean and jerk practice allows each part to be checked. Choose load and combination with the coach according to technique; repetition count alone does not justify increasing weight."]}}},"ex26_split_jerk":{"id":"ex26_split_jerk","edits":{"cz":"Výraz do střihu ze stojanu","en":"Split Jerk from Rack","eq":["cinka","barbell_rack","weightlifting_area"],"foc":["Samostatný výraz z ramen do střihu bez předchozího přemístění ze země.","An isolated split jerk from the shoulders without a preceding floor clean."],"pos":["Nastav stojan pro odebrání osy na přední stranu ramen. Odeber lehkou činku a odstup do volné plochy. Připrav stabilní postoj, dostatek výšky a nacvičený návrat; háky nesmějí zasahovat do střihu.","Set the rack to take the bar onto the front shoulders. Unrack a light bar and step into the clear lifting area. Establish a stable stance, overhead clearance and a practised return; the hooks must not obstruct the split."],"exe":["Se svislým trupem krátce pokrč kolena a nohy rychle propni. Přesuň chodidla do střihu a přijmi osu na napnuté paže. Po ustálení sbírej nejprve přední chodidlo část cesty zpět a potom zadní vpřed. Vrať činku na ramena nacvičeným způsobem; po sérii ji ulož do stojanu.","Dip with a vertical trunk and drive with the legs. Move the feet into a split and receive the bar on straight arms. Once stable, recover the front foot partway back and then the rear foot forward. Return to the shoulders by the practised method and rack the bar after the set."],"wat":["Přední chodidlo má oporu, zadní pata je nahoře a zadní koleno není zamčené. Nezaměňuj výraz za pomalé dotlačení. Před přidáním zátěže se s trenérem nauč i přerušení pokusu a odložení.","Keep the front foot supported, the rear heel raised and the rear knee unlocked. Do not replace the receive with a slow press-out. Learn aborting and lowering with a coach before increasing load."],"pro":["Kroky do střihu a práce s lehkou tyčí jsou příprava, nikoli automatická rozcvičovací série s procenty pracovní váhy. Rychlost, zátěž a návrat upravuj ručně podle techniky.","Split footwork and light-dowel drills are preparation, not an automatic warm-up series based on working-weight percentages. Adjust speed, load and return manually according to technique."],"equipmentDetail":["Velká činka, stojan pro odebrání na ramena a vhodná plocha s výškou nad hlavou. Jeden výraz s návratem do stoje je jedno opakování; odebrání ze stojanu se nepočítá jako přemístění. Kg označují celou osu s kotouči.","Barbell, a rack suitable for taking it onto the shoulders and an appropriate area with overhead clearance. One jerk and recovery to standing counts as one repetition; unracking is not a clean. Kilograms refer to the whole bar and plates."],"source":{"author":"American Council on Exercise","document":"Push Jerk — text describes a split receive from a rack","url":"https://www.acefitness.org/resources/everyone/exercise-library/313/push-jerk/"}},"taxonomy":{"regions":["hips","thighs","shoulders"],"secondaryRegions":["trunk","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["cinka"],["barbell_rack","squat_rack"],["weightlifting_area"]],"aliases":["Výraz do střihu ze stojanu","Split Jerk from Rack"]},"policy":{"id":"ex26_split_jerk","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["cinka"],["barbell_rack","squat_rack"],["weightlifting_area"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-jerk-total-barbell-mass","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_split_jerk","atlasId":"ex26_split_jerk","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"48e95d11a2cae149d0273246962b24f42866eb5ae73ca88fd537e34af02c0992","thumb":"/expansion-atlas/ex26_split_jerk-original-256.webp","detail":"/expansion-atlas/ex26_split_jerk-original-960.webp","inkThumb":"/expansion-atlas/ex26_split_jerk-ink-256.webp","inkDetail":"/expansion-atlas/ex26_split_jerk-ink-960.webp","fillThumb":"/expansion-atlas/ex26_split_jerk-fill-256.webp","fillDetail":"/expansion-atlas/ex26_split_jerk-fill-960.webp"},"sourceSha256":"48e95d11a2cae149d0273246962b24f42866eb5ae73ca88fd537e34af02c0992","contourOnly":true,"darkOutline":true},"equipmentLabels":["Velká činka; stojan pro odebrání na ramena; vhodná plocha a výška","Barbell; rack for shoulder-height pickup; suitable area and overhead clearance"],"libraryOrders":{"weightlifting":11},"deliveryProfiles":{"d5d894df2b9d5b9f":{"fields":{"id":"ex26_split_jerk","cz":"Výraz do střihu ze stojanu","en":"Split Jerk from Rack","pat":"tlak","eq":["cinka","barbell_rack","weightlifting_area"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Samostatný výraz z ramen do střihu bez předchozího přemístění ze země.","An isolated split jerk from the shoulders without a preceding floor clean."],"startPosition":["Nastav stojan pro odebrání osy na přední stranu ramen. Odeber lehkou činku a odstup do volné plochy. Připrav stabilní postoj, dostatek výšky a nacvičený návrat; háky nesmějí zasahovat do střihu.","Set the rack to take the bar onto the front shoulders. Unrack a light bar and step into the clear lifting area. Establish a stable stance, overhead clearance and a practised return; the hooks must not obstruct the split."],"execution":["Se svislým trupem krátce pokrč kolena a nohy rychle propni. Přesuň chodidla do střihu a přijmi osu na napnuté paže. Po ustálení sbírej nejprve přední chodidlo část cesty zpět a potom zadní vpřed. Vrať činku na ramena nacvičeným způsobem; po sérii ji ulož do stojanu.","Dip with a vertical trunk and drive with the legs. Move the feet into a split and receive the bar on straight arms. Once stable, recover the front foot partway back and then the rear foot forward. Return to the shoulders by the practised method and rack the bar after the set."],"watchFor":["Přední chodidlo má oporu, zadní pata je nahoře a zadní koleno není zamčené. Nezaměňuj výraz za pomalé dotlačení. Před přidáním zátěže se s trenérem nauč i přerušení pokusu a odložení.","Keep the front foot supported, the rear heel raised and the rear knee unlocked. Do not replace the receive with a slow press-out. Learn aborting and lowering with a coach before increasing load."]},"progression":["Kroky do střihu a práce s lehkou tyčí jsou příprava, nikoli automatická rozcvičovací série s procenty pracovní váhy. Rychlost, zátěž a návrat upravuj ručně podle techniky.","Split footwork and light-dowel drills are preparation, not an automatic warm-up series based on working-weight percentages. Adjust speed, load and return manually according to technique."]}}},"ex26_kb_split_jerk":{"id":"ex26_kb_split_jerk","edits":{"cz":"Výraz dvou kettlebellů do střihu","en":"Double-Kettlebell Split Jerk","eq":["kettlebell_pair","prostor"],"foc":["Dva kettlebelly z přední opory na ramenou do střihu nad hlavou.","Move two kettlebells from the front rack into an overhead split receive."],"pos":["Připrav dva lehké kettlebelly v přední oporové poloze u ramen a volné okolí i výšku. Zvolenou přední nohu a návrat nejprve procvič s trenérem bez těžké zátěže.","Prepare two light kettlebells in the front rack with clear surrounding and overhead space. First practise the chosen lead leg and return with a coach without heavy loads."],"exe":["Krátce pokrč kolena a odrazem nohou zvedni obě závaží. Přijmi je na napnuté paže ve střihu. Ustal, přisuň přední chodidlo část cesty zpět a zadní vpřed do stoje. Kontrolovaně vrať oba kettlebelly do přední opory.","Use a short knee dip and leg drive to raise both bells. Receive on straight arms in a split. Stabilize, recover the front foot partway back and the rear foot forward to standing, then lower both bells under control to the front rack."],"wat":["Přední chodidlo opři, zadní patu nech nahoře a koleno měkké. Při nejistém úchopu, bolesti nebo ztrátě kontroly skonči. Jeden kettlebell nebo tlak bez střihu jsou jiné úkoly.","Support the front foot, raise the rear heel and keep that knee soft. Stop for an insecure grip, pain or lost control. One bell or a press without a split is a different task."],"pro":["Nejdřív zvládni přední oporu, výpon s odrazem a střih s lehkým párem. Dávku a zátěž měň ručně; přední nohu nestřídej automaticky po každém opakování.","First establish the rack, leg drive and split with a light pair. Change dose and load manually; do not automatically alternate the lead leg on every repetition."],"equipmentDetail":["Pár kettlebellů a volný prostor včetně výšky nad hlavou. Pro nový záznam zapisuj součet hmotností obou a jejich jednotlivé hmotnosti uveď do poznámky. U starých kg nevíme, zda šlo o kus nebo součet: neměníme je ani je neporovnáváme. Jeden výraz obou kettlebellů je jedno opakování, bez dělení na levou a pravou stranu.","A pair of kettlebells and clear space including overhead clearance. For a new record enter the combined mass and note each bell separately. Older kilograms may mean one bell or the pair: leave them unchanged and do not compare them. One jerk with both bells is one repetition, without separate left and right sets."],"source":{"author":"American Council on Exercise","document":"Push-jerk — two kettlebells with a split receive","url":"https://www.acefitness.org/resources/everyone/exercise-library/385/push-jerk/"}},"taxonomy":{"regions":["hips","thighs","shoulders"],"secondaryRegions":["trunk","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell_pair"],["prostor"]],"aliases":["Výraz dvou kettlebellů do střihu","Double-Kettlebell Split Jerk"]},"policy":{"id":"ex26_kb_split_jerk","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["kettlebell_pair"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-double-jerk-new-total-pair-mass-historical-convention-unknown","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_kb_split_jerk","atlasId":"ex26_kb_split_jerk","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"677a777e0a7d7e95bdd684d991ff494afa7b0963ed587ecfc34246feab26c4b1","thumb":"/expansion-atlas/ex26_kb_split_jerk-original-256.webp","detail":"/expansion-atlas/ex26_kb_split_jerk-original-960.webp","inkThumb":"/expansion-atlas/ex26_kb_split_jerk-ink-256.webp","inkDetail":"/expansion-atlas/ex26_kb_split_jerk-ink-960.webp","fillThumb":"/expansion-atlas/ex26_kb_split_jerk-fill-256.webp","fillDetail":"/expansion-atlas/ex26_kb_split_jerk-fill-960.webp"},"sourceSha256":"677a777e0a7d7e95bdd684d991ff494afa7b0963ed587ecfc34246feab26c4b1","contourOnly":true,"darkOutline":true},"equipmentLabels":["Dva kettlebelly; volný prostor a výška nad hlavou","Two kettlebells; surrounding and overhead clearance"],"libraryOrders":{"weightlifting":13},"deliveryProfiles":{"10f9918c094cdf4c":{"fields":{"id":"ex26_kb_split_jerk","cz":"Výraz dvou kettlebellů do střihu","en":"Double-Kettlebell Split Jerk","pat":"tlak","eq":["kettlebell_pair","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Dva kettlebelly z přední opory na ramenou do střihu nad hlavou.","Move two kettlebells from the front rack into an overhead split receive."],"startPosition":["Připrav dva lehké kettlebelly v přední oporové poloze u ramen a volné okolí i výšku. Zvolenou přední nohu a návrat nejprve procvič s trenérem bez těžké zátěže.","Prepare two light kettlebells in the front rack with clear surrounding and overhead space. First practise the chosen lead leg and return with a coach without heavy loads."],"execution":["Krátce pokrč kolena a odrazem nohou zvedni obě závaží. Přijmi je na napnuté paže ve střihu. Ustal, přisuň přední chodidlo část cesty zpět a zadní vpřed do stoje. Kontrolovaně vrať oba kettlebelly do přední opory.","Use a short knee dip and leg drive to raise both bells. Receive on straight arms in a split. Stabilize, recover the front foot partway back and the rear foot forward to standing, then lower both bells under control to the front rack."],"watchFor":["Přední chodidlo opři, zadní patu nech nahoře a koleno měkké. Při nejistém úchopu, bolesti nebo ztrátě kontroly skonči. Jeden kettlebell nebo tlak bez střihu jsou jiné úkoly.","Support the front foot, raise the rear heel and keep that knee soft. Stop for an insecure grip, pain or lost control. One bell or a press without a split is a different task."]},"progression":["Nejdřív zvládni přední oporu, výpon s odrazem a střih s lehkým párem. Dávku a zátěž měň ručně; přední nohu nestřídej automaticky po každém opakování.","First establish the rack, leg drive and split with a light pair. Change dose and load manually; do not automatically alternate the lead leg on every repetition."]}}},"kbclean":{"id":"kbclean","edits":{"cz":"Švihové přemístění kettlebellu","en":"Single-Kettlebell Swing Clean","eq":["kettlebell","prostor"],"load":"ext","measurementType":"WEIGHT_REPS","foc":["Kyčelní odraz a klidné zachycení jednoho kettlebellu u ramene.","Hip drive and a controlled single-kettlebell receive at the shoulder."],"pos":["Postav lehký kettlebell před chodidla, ustal postoj a uchop ho jednou rukou z předklonu v kyčlích. Nech prostor pro zášvih i volnou ruku.","Place a light kettlebell ahead of the feet, establish a stable stance and grip it with one hand from a hip hinge. Leave room for the backswing and free arm."],"exe":["Zatáhni kettlebell mezi stehna a odrazem kyčlí jej veď vzhůru blízko těla. Vsuň ruku do madla a nech závaží měkce dosednout u předloktí a ramene. Po ustálení jej vrať do zášvihu pro další přemístění; po sérii jej odlož.","Hike the bell between the thighs and use hip drive to guide it upward close to the body. Insert the hand through the handle and receive softly by the forearm and shoulder. Once stable, return to the backswing for the next clean; park the bell after the set."],"wat":["Netahej pohyb jako bicepsový zdvih a nenech kettlebell přepadnout přes zápěstí. Pokud naráží do předloktí, sniž náročnost a oprav vedení s trenérem. Volnou ruku drž mimo dráhu.","Avoid turning the movement into an arm curl or letting the bell flip over the wrist. If it strikes the forearm, reduce difficulty and review the path with a coach. Keep the free hand outside the path."],"pro":["Nejprve nacvič kyčelní ohyb, zášvih a oporu u ramene. Náročnost upravuj ručně podle kontroly; přechod na pár či vyšší váhu není automatická další úroveň.","Practise the hinge, backswing and rack first. Adjust difficulty manually according to control; a pair or a heavier bell is not an automatic next level."],"equipmentDetail":["Jeden kettlebell a volný prostor. Nové opakování je jeden příjem u ramene; ve společném záznamu počítej jednotlivé příjmy obou rukou celkem, ne dvojnásobně. Stranu můžeš změnit po odložení, není nutná výměna ve vzduchu. Staré společné počty nerozdělujeme na strany. Kg jsou hmotnost použitého kettlebellu.","One kettlebell and clear space. One new repetition is one rack receive; a combined record counts individual receives across both arms in total, without doubling. Change hands after parking if needed; no mid-air exchange is required. Earlier combined counts are not split by side. Kilograms are the mass of the bell used."],"source":{"author":"Damali Fraiser / Girls Gone Strong","document":"Unlock The Power of The Kettlebell Clean — swing clean","url":"https://www.girlsgonestrong.com/blog/strength-training/kettlebell-clean/"}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":["trunk","shoulders","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Přemístění kettlebellu","Kettlebell Clean"]},"policy":{"id":"kbclean","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"alternating","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"single-bell-combined-receive-count-no-historical-side-inference","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"sideMeaning":["Pracující ruka; společný počet","Working hand; combined count"],"sideNote":["Společný počet sčítá jednotlivé pohyby obou rukou. Nemění se na stejný počet na každou stranu a staré L/R nevykládáme.","The combined count totals individual movements by both hands. It is not converted into that many per side; earlier L/R are not reinterpreted."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"kbclean","atlasId":"kbclean","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"0c801713844a17aa8643dac880b39ef4d013e70f3cfb9732cafd2db63210a81a","thumb":"/unified-atlas/kbclean-10536b5288b2f864-thumb.webp","detail":"/unified-atlas/kbclean-525e2e147cf4e8a6-detail.webp","inkThumb":"/unified-atlas/kbclean-8025dae4bca6fe1b-inkThumb.webp","inkDetail":"/unified-atlas/kbclean-7d9d720c3c69f2f3-inkDetail.webp","fillThumb":"/unified-atlas/kbclean-ddaa93a16fdb9202-fillThumb.webp","fillDetail":"/unified-atlas/kbclean-8928d9b46dc77beb-fillDetail.webp"},"sourceSha256":"0c801713844a17aa8643dac880b39ef4d013e70f3cfb9732cafd2db63210a81a","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell; prostor pro zášvih a odložení","One kettlebell; space for backswing and parking"],"libraryOrders":{"weightlifting":0},"deliveryProfiles":{"8b0d6e9dce623244":{"fields":{"id":"kbclean","cz":"Švihové přemístění kettlebellu","en":"Single-Kettlebell Swing Clean","pat":"ohyb","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":true,"sideMode":"alternating","focus":["Kyčelní odraz a klidné zachycení jednoho kettlebellu u ramene.","Hip drive and a controlled single-kettlebell receive at the shoulder."],"startPosition":["Postav lehký kettlebell před chodidla, ustal postoj a uchop ho jednou rukou z předklonu v kyčlích. Nech prostor pro zášvih i volnou ruku.","Place a light kettlebell ahead of the feet, establish a stable stance and grip it with one hand from a hip hinge. Leave room for the backswing and free arm."],"execution":["Zatáhni kettlebell mezi stehna a odrazem kyčlí jej veď vzhůru blízko těla. Vsuň ruku do madla a nech závaží měkce dosednout u předloktí a ramene. Po ustálení jej vrať do zášvihu pro další přemístění; po sérii jej odlož.","Hike the bell between the thighs and use hip drive to guide it upward close to the body. Insert the hand through the handle and receive softly by the forearm and shoulder. Once stable, return to the backswing for the next clean; park the bell after the set."],"watchFor":["Netahej pohyb jako bicepsový zdvih a nenech kettlebell přepadnout přes zápěstí. Pokud naráží do předloktí, sniž náročnost a oprav vedení s trenérem. Volnou ruku drž mimo dráhu.","Avoid turning the movement into an arm curl or letting the bell flip over the wrist. If it strikes the forearm, reduce difficulty and review the path with a coach. Keep the free hand outside the path."]},"progression":["Nejprve nacvič kyčelní ohyb, zášvih a oporu u ramene. Náročnost upravuj ručně podle kontroly; přechod na pár či vyšší váhu není automatická další úroveň.","Practise the hinge, backswing and rack first. Adjust difficulty manually according to control; a pair or a heavier bell is not an automatic next level."]}}},"ex26_kb_double_clean":{"id":"ex26_kb_double_clean","edits":{"cz":"Švihové přemístění dvou kettlebellů","en":"Double-Kettlebell Swing Clean","eq":["kettlebell_pair","prostor"],"foc":["Současný příjem dvou kettlebellů u ramen po odrazu kyčlí.","Receive two kettlebells together at the shoulders after hip drive."],"pos":["Postav dva lehké kettlebelly před sebe. Ustal postoj tak, aby oba prošly mezi stehny, a uchop každé madlo jednou rukou.","Place two light kettlebells ahead. Use a stable stance wide enough for both bells to pass between the thighs and grip one handle in each hand."],"exe":["Veď oba kettlebelly do krátkého zášvihu a kyčlemi je přiveď těsně k tělu. Vsuň ruce do madel, měkce přijmi obě závaží u ramen a ustal. Kontrolovaným návratem do zášvihu připrav další příjem, nebo pár odlož.","Hike both bells and use hip drive to bring them close to the body. Insert the hands, receive softly at the shoulders and stabilize. Return under control into the backswing for another receive, or park the pair."],"wat":["Obě závaží musí mít volnou dráhu kolem kolen a klidně dosednout u předloktí. Neřeš nárazy silnějším sevřením nebo větší rychlostí; zjednoduš úkol a ověř vedení.","Leave a clear path around the knees and receive both bells softly by the forearms. Do not solve impacts by gripping harder or moving faster; simplify the task and check the path."],"pro":["Jednoruční přemístění umožní procvičit příjem zvlášť. Pár mění průchod i rovnováhu zátěže; připrav jej samostatně a neodvozuj pracovní váhu z pouhého dvojnásobku jedné činky.","A single-bell clean lets each receive be practised separately. A pair changes clearance and load balance; prepare it separately and do not infer its working load simply by doubling one bell."],"equipmentDetail":["Pár kettlebellů a volný prostor. Jeden současný příjem páru je jedno opakování bez L/R sad. Pro nový záznam kg použij součet obou a do poznámky napiš hmotnost jednotlivých kusů. Staré kg mohou znamenat kus nebo pár: zachováváme je bez přepočtu a bez porovnávání.","A pair of kettlebells and clear space. One simultaneous receive of the pair counts as one repetition without L/R sets. For a new kilogram record use the combined mass and note each bell separately. Earlier kilograms may mean one bell or the pair: preserve them without conversion or comparison."],"source":{"author":"Kenneth Bolyard / StrongFirst","document":"The Kur for Your Kettlebell Swing and Clean — single and double clean mechanics","url":"https://www.strongfirst.com/the-kur-for-your-kettlebell-swing-and-clean/"}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":["trunk","shoulders","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell_pair"],["prostor"]],"aliases":["Přemístění dvou kettlebellů","Double-Kettlebell Clean"]},"policy":{"id":"ex26_kb_double_clean","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["kettlebell_pair"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-pair-receive-new-total-mass-historical-convention-unknown","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_kb_double_clean","atlasId":"ex26_kb_double_clean","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"321e4f765380fa406a6d3cc391df9caf7f9eddd0a47977bd799b1afadd120eae","thumb":"/expansion-atlas/ex26_kb_double_clean-original-256.webp","detail":"/expansion-atlas/ex26_kb_double_clean-original-960.webp","inkThumb":"/expansion-atlas/ex26_kb_double_clean-ink-256.webp","inkDetail":"/expansion-atlas/ex26_kb_double_clean-ink-960.webp","fillThumb":"/expansion-atlas/ex26_kb_double_clean-fill-256.webp","fillDetail":"/expansion-atlas/ex26_kb_double_clean-fill-960.webp"},"sourceSha256":"321e4f765380fa406a6d3cc391df9caf7f9eddd0a47977bd799b1afadd120eae","contourOnly":true,"darkOutline":true},"equipmentLabels":["Dva kettlebelly; prostor pro současný průchod a odložení","Two kettlebells; space for simultaneous passage and parking"],"libraryOrders":{"weightlifting":3},"deliveryProfiles":{"3ad3304ea0dcaded":{"fields":{"id":"ex26_kb_double_clean","cz":"Švihové přemístění dvou kettlebellů","en":"Double-Kettlebell Swing Clean","pat":"ohyb","eq":["kettlebell_pair","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Současný příjem dvou kettlebellů u ramen po odrazu kyčlí.","Receive two kettlebells together at the shoulders after hip drive."],"startPosition":["Postav dva lehké kettlebelly před sebe. Ustal postoj tak, aby oba prošly mezi stehny, a uchop každé madlo jednou rukou.","Place two light kettlebells ahead. Use a stable stance wide enough for both bells to pass between the thighs and grip one handle in each hand."],"execution":["Veď oba kettlebelly do krátkého zášvihu a kyčlemi je přiveď těsně k tělu. Vsuň ruce do madel, měkce přijmi obě závaží u ramen a ustal. Kontrolovaným návratem do zášvihu připrav další příjem, nebo pár odlož.","Hike both bells and use hip drive to bring them close to the body. Insert the hands, receive softly at the shoulders and stabilize. Return under control into the backswing for another receive, or park the pair."],"watchFor":["Obě závaží musí mít volnou dráhu kolem kolen a klidně dosednout u předloktí. Neřeš nárazy silnějším sevřením nebo větší rychlostí; zjednoduš úkol a ověř vedení.","Leave a clear path around the knees and receive both bells softly by the forearms. Do not solve impacts by gripping harder or moving faster; simplify the task and check the path."]},"progression":["Jednoruční přemístění umožní procvičit příjem zvlášť. Pár mění průchod i rovnováhu zátěže; připrav jej samostatně a neodvozuj pracovní váhu z pouhého dvojnásobku jedné činky.","A single-bell clean lets each receive be practised separately. A pair changes clearance and load balance; prepare it separately and do not infer its working load simply by doubling one bell."]}}},"kb26_dead_clean":{"id":"kb26_dead_clean","edits":{"cz":"Švihové přemístění kettlebellu s odložením","en":"Dead-Stop Single-Kettlebell Swing Clean","eq":["kettlebell","prostor"],"foc":["Jednotlivá přemístění s krátkým zášvihem a úplným odložením mezi nimi.","Individual cleans with a short backswing and full parking between repetitions."],"pos":["Polož kettlebell blízko před chodidla. Uchop jej jednou rukou z pevného kyčelního předklonu; každé nové opakování připrav z klidu.","Place the bell close ahead of the feet. Grip with one hand from a braced hip hinge and prepare each new repetition from rest."],"exe":["Krátkým zášvihem zatáhni kettlebell mezi stehna. Odrazem kyčlí jej veď blízko těla, vsuň ruku do madla a přijmi u ramene. Přes kontrolovaný zášvih jej vrať na zem, nech zastavit a znovu se nastav.","Use a short hike between the thighs. Drive with the hips, guide the bell close, insert the hand and receive at the shoulder. Return through a controlled backswing to the floor, let it stop and reset."],"wat":["Tato varianta stále obsahuje zášvih; není to svislý dead clean bez něj. Kettlebell se mezi pokusy zcela zastaví a nedopadá na zápěstí. Při bolesti nebo ztrátě kontroly skonči.","This version still has a backswing; it is not a vertical dead clean without one. Let the bell stop fully between attempts and avoid wrist impact. Stop for pain or loss of control."],"pro":["Odložení umožňuje znovu připravit start. Plynulá přemístění jsou jiná organizace opakování, ne povinný vyšší stupeň. Měň pouze to, co zvládáš kontrolovat.","Parking allows the start to be reset. Continuous cleans use a different repetition structure, not a compulsory higher level. Change only what remains controlled."],"equipmentDetail":["Jeden kettlebell a volný prostor pro zášvih i odložení. Jedno přemístění a návrat na zem je jedno opakování na zapsanou stranu. Záznamy L/R a původní dávky zůstávají samostatné; kg jsou hmotnost použitého kettlebellu.","One kettlebell and space for the backswing and parking. One clean and return to the floor is one repetition on the recorded side. Existing L/R records and doses remain separate; kilograms are the mass of the bell used."],"source":{"author":"Kenneth Bolyard / StrongFirst","document":"The Kur for Your Kettlebell Swing and Clean — Dead-Stop Clean","url":"https://www.strongfirst.com/the-kur-for-your-kettlebell-swing-and-clean/"}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":["trunk","shoulders","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Přemístění kettlebellu s odložením mezi opakováními","Dead-Stop Kettlebell Clean"]},"policy":{"id":"kb26_dead_clean","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"single-bell-one-reset-cycle-per-recorded-side","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"sideMeaning":["Pracující ruka","Working hand"],"sideNote":["Pro nový plán označ ruku držící náčiní. Jeden úplný pohyb na této ruce je jedno opakování; nejde o dvojnásobek. Význam platí pro nové zadání. Dřívější L/R ani neurčenou stranu nepřeznačujeme.","For a new plan identify the hand holding the implement. One complete movement with that hand is one repetition, without doubling. This meaning applies to a new prescription. Earlier L/R and unspecified sides are not relabelled."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false,"preserveSide":true},"art":{"appId":"kb26_dead_clean","atlasId":"kb26_dead_clean","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"d809054130872ccbcf15d3d13ca3e28521e025a7b89a920b4ac94a1c4f104f8d","thumb":"/expansion-atlas/kb26_dead_clean-original-256.webp","detail":"/expansion-atlas/kb26_dead_clean-original-960.webp","inkThumb":"/expansion-atlas/kb26_dead_clean-ink-256.webp","inkDetail":"/expansion-atlas/kb26_dead_clean-ink-960.webp","fillThumb":"/expansion-atlas/kb26_dead_clean-fill-256.webp","fillDetail":"/expansion-atlas/kb26_dead_clean-fill-960.webp"},"sourceSha256":"d809054130872ccbcf15d3d13ca3e28521e025a7b89a920b4ac94a1c4f104f8d","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell; prostor pro zášvih a odložení","One kettlebell; space for backswing and parking"],"libraryOrders":{"weightlifting":1},"deliveryProfiles":{"486e7e5319ce8898":{"fields":{"id":"kb26_dead_clean","cz":"Švihové přemístění kettlebellu s odložením","en":"Dead-Stop Single-Kettlebell Swing Clean","pat":"ohyb","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":true,"sideMode":"perSide","focus":["Jednotlivá přemístění s krátkým zášvihem a úplným odložením mezi nimi.","Individual cleans with a short backswing and full parking between repetitions."],"startPosition":["Polož kettlebell blízko před chodidla. Uchop jej jednou rukou z pevného kyčelního předklonu; každé nové opakování připrav z klidu.","Place the bell close ahead of the feet. Grip with one hand from a braced hip hinge and prepare each new repetition from rest."],"execution":["Krátkým zášvihem zatáhni kettlebell mezi stehna. Odrazem kyčlí jej veď blízko těla, vsuň ruku do madla a přijmi u ramene. Přes kontrolovaný zášvih jej vrať na zem, nech zastavit a znovu se nastav.","Use a short hike between the thighs. Drive with the hips, guide the bell close, insert the hand and receive at the shoulder. Return through a controlled backswing to the floor, let it stop and reset."],"watchFor":["Tato varianta stále obsahuje zášvih; není to svislý dead clean bez něj. Kettlebell se mezi pokusy zcela zastaví a nedopadá na zápěstí. Při bolesti nebo ztrátě kontroly skonči.","This version still has a backswing; it is not a vertical dead clean without one. Let the bell stop fully between attempts and avoid wrist impact. Stop for pain or loss of control."]},"progression":["Odložení umožňuje znovu připravit start. Plynulá přemístění jsou jiná organizace opakování, ne povinný vyšší stupeň. Měň pouze to, co zvládáš kontrolovat.","Parking allows the start to be reset. Continuous cleans use a different repetition structure, not a compulsory higher level. Change only what remains controlled."]}}},"kbhighpull":{"id":"kbhighpull","edits":{"cz":"Švihový vysoký tah kettlebellu","en":"Kettlebell Swing High Pull","eq":["kettlebell","prostor"],"load":"ext","measurementType":"WEIGHT_REPS","foc":["Odraz kyčlí a přiblížení kettlebellu pokrčením lokte, bez příjmu nad hlavou.","Hip drive and elbow bending to draw the bell closer, without an overhead receive."],"pos":["Připrav lehký kettlebell před chodidly a volnou dráhu před tělem. Uchop jej jednou rukou ze stabilního předklonu v kyčlích.","Prepare a light kettlebell ahead of the feet and clear space in front. Grip it with one hand from a stable hip hinge."],"exe":["Po zášvihu zrychli kettlebell odrazem kyčlí. Až se odlehčí, pokrč loket a veď ho ven a zpět, aby se kettlebell přiblížil. Znovu natáhni paži a vrať závaží do kontrolovaného zášvihu. Po sérii jej odlož.","After the backswing, accelerate the bell with hip drive. As it floats, bend and guide the elbow outward and back to bring the bell closer. Lengthen the arm again and return into a controlled backswing. Park the bell after the set."],"wat":["Není to pomalý přítah k bradě ani tlak nad hlavu. Netlač loket do maximální výšky a nenahrazuj odraz škubnutím ramenem. Pokud nedokážeš řídit návrat, zvol jednodušší švih a ověř provedení s trenérem.","This is not a slow upright row or an overhead press. Do not force maximal elbow height or replace hip drive with a shoulder yank. If the return is uncontrolled, use a simpler swing and review the technique with a coach."],"pro":["Může sloužit jako samostatný technický úkol pro vedení kettlebellu nebo jako průprava. Trh není povinné pokračování a přidávání váhy se neřídí automaticky splněným počtem.","Use it as a technical bell-path task or as preparation. A snatch is not a compulsory continuation and completed repetitions do not automatically justify adding load."],"equipmentDetail":["Jeden kettlebell a volný prostor pro zášvih. Jedno přitažení a návrat je jedno opakování; kg jsou hmotnost tohoto kettlebellu. Karta má historicky společný záznam bez L/R: staré počty ani strany z něj neodvozujeme. U nového plánu uveď použitou ruku v zadání.","One kettlebell and space for the backswing. One pull and return is one repetition; kilograms are the mass of that bell. This card historically has a combined record without L/R: do not infer old sides or redistribute counts. Specify the working hand in a new prescription."],"source":{"author":"Lance Coffel, Fabio Zonin, Brett Jones / StrongFirst","document":"Kettlebell Fundamentals — Module9: High Pull","url":"https://strongfirst.skilltrain.com/Pages/Public/Lesson?enc=Bf1%2F7z5IBsE1THj04sy6OA%3D%3D","scope":"Public lesson overview confirms the high-pull task; full lesson and detailed demonstration were not viewed. Existing swing-path intent is retained, not represented as a newly verified course transcript."}},"taxonomy":{"regions":["hips","shoulders"],"secondaryRegions":["thighs","trunk","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Tah kettlebellu k ramenům","Kettlebell High Pull"]},"policy":{"id":"kbhighpull","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"single-bell-pull-return-no-historical-side-inference","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"sideMeaning":["Pracující ruka v zadání","Working hand in the prescription"],"sideNote":["Karta zachovává společný záznam bez rozdělení L/R. Použitou ruku určete v novém zadání, staré počty nerozdělujeme.","This card keeps a combined record without L/R splits. Specify the working hand in a new prescription; earlier counts are not divided."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"kbhighpull","atlasId":"kbhighpull","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"431cfd50748a2265d9ef53823db1aa8e3bf627bfeb1ed94f0763e3651c2d646a","thumb":"/unified-atlas/kbhighpull-9966e6fc99439c2e-thumb.webp","detail":"/unified-atlas/kbhighpull-64381ce8294a021e-detail.webp","inkThumb":"/unified-atlas/kbhighpull-7425083fca7c5f9e-inkThumb.webp","inkDetail":"/unified-atlas/kbhighpull-c30c232e29dd2325-inkDetail.webp","fillThumb":"/unified-atlas/kbhighpull-2d9c485322cb4e60-fillThumb.webp","fillDetail":"/unified-atlas/kbhighpull-ad34e3d3153a1b1b-fillDetail.webp"},"sourceSha256":"431cfd50748a2265d9ef53823db1aa8e3bf627bfeb1ed94f0763e3651c2d646a","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell; prostor pro zášvih a návrat","One kettlebell; space for backswing and return"],"libraryOrders":{"weightlifting":2},"deliveryProfiles":{"2ed5775fd2491173":{"fields":{"id":"kbhighpull","cz":"Švihový vysoký tah kettlebellu","en":"Kettlebell Swing High Pull","pat":"ohyb","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":90,"unilateral":false,"sideMode":"none","focus":["Odraz kyčlí a přiblížení kettlebellu pokrčením lokte, bez příjmu nad hlavou.","Hip drive and elbow bending to draw the bell closer, without an overhead receive."],"startPosition":["Připrav lehký kettlebell před chodidly a volnou dráhu před tělem. Uchop jej jednou rukou ze stabilního předklonu v kyčlích.","Prepare a light kettlebell ahead of the feet and clear space in front. Grip it with one hand from a stable hip hinge."],"execution":["Po zášvihu zrychli kettlebell odrazem kyčlí. Až se odlehčí, pokrč loket a veď ho ven a zpět, aby se kettlebell přiblížil. Znovu natáhni paži a vrať závaží do kontrolovaného zášvihu. Po sérii jej odlož.","After the backswing, accelerate the bell with hip drive. As it floats, bend and guide the elbow outward and back to bring the bell closer. Lengthen the arm again and return into a controlled backswing. Park the bell after the set."],"watchFor":["Není to pomalý přítah k bradě ani tlak nad hlavu. Netlač loket do maximální výšky a nenahrazuj odraz škubnutím ramenem. Pokud nedokážeš řídit návrat, zvol jednodušší švih a ověř provedení s trenérem.","This is not a slow upright row or an overhead press. Do not force maximal elbow height or replace hip drive with a shoulder yank. If the return is uncontrolled, use a simpler swing and review the technique with a coach."]},"progression":["Může sloužit jako samostatný technický úkol pro vedení kettlebellu nebo jako průprava. Trh není povinné pokračování a přidávání váhy se neřídí automaticky splněným počtem.","Use it as a technical bell-path task or as preparation. A snatch is not a compulsory continuation and completed repetitions do not automatically justify adding load."]}}},"kbsnatch":{"id":"kbsnatch","edits":{"cz":"Švihový trh kettlebellem","en":"Kettlebell Swing Snatch","eq":["kettlebell","prostor"],"load":"ext","measurementType":"WEIGHT_REPS","foc":["Plynulý přechod ze zášvihu do ustálené natažené paže nad hlavou.","Move continuously from the backswing into a stable straight-arm overhead position."],"pos":["Připrav lehký kettlebell před chodidly, volný prostor a výšku nad hlavou. Zpevni kyčelní předklon a uchop madlo jednou rukou. Nácvik příjmu i spouštění proveď s trenérem.","Prepare a light kettlebell ahead of the feet with clear surrounding and overhead space. Brace in a hip hinge and grip with one hand. Practise receiving and lowering with a coach."],"exe":["Ze zášvihu zrychli odrazem kyčlí a veď kettlebell blízko těla. Vsuň ruku do madla a ustal nataženou paži nad hlavou ve stoji. Nacvičeným řízeným návratem spusť kettlebell do zášvihu pro další trh, nebo jej odlož.","Accelerate from the backswing with hip drive and keep the bell close. Insert the hand through the handle and stabilize overhead on a straight arm while standing. Use the practised controlled return to the backswing for another snatch, or park the bell."],"wat":["Nahoře se ustal bez dotlačování a bez přepadnutí kettlebellu na předloktí. Paži nenarovnávej násilím přes bolest a bedry nenahrazuj chybějící polohu nad hlavou. Nezvyšuj dávku, pokud se zhoršuje příjem či návrat.","Stabilize without pressing out or letting the bell crash onto the forearm. Do not force the arm straight through pain or compensate with the lower back for the overhead position. Do not increase the dose when receiving or lowering deteriorates."],"pro":["Švih, přemístění a samotná kontrola nad hlavou mohou připravit dílčí dovednosti. Nejsou časovým ani zátěžovým žebříčkem. Plný trh a jeho návrat posuzuj samostatně s trenérem.","Swings, cleans and overhead control can prepare individual skills. They are not a time or loading ladder. Review the complete snatch and its return separately with a coach."],"equipmentDetail":["Jeden kettlebell a prostor včetně výšky nad hlavou. Jeden ustálený trh je jedno opakování; společný záznam sečte jednotlivé trhy obou rukou bez násobení. Změnu ruky lze provést po odložení. Historické alternating počty neproměňujeme na počet pro každou stranu; kg jsou jedna činka.","One kettlebell and space including overhead clearance. One stabilized snatch is one repetition; the combined record totals individual snatches across both hands without multiplying them. Hands may be changed after parking. Do not turn historical alternating totals into per-side counts; kilograms mean one bell."],"source":{"author":"StrongFirst","document":"SFGI requirements — snatch movement description, not test prescription","url":"https://www.strongfirst.com/certifications/sfg-i-requirements/"}},"taxonomy":{"regions":["hips","shoulders"],"secondaryRegions":["thighs","trunk","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Trh kettlebellem","Kettlebell Snatch"]},"policy":{"id":"kbsnatch","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"alternating","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"single-bell-combined-snatch-count","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"sideMeaning":["Pracující ruka; společný počet","Working hand; combined count"],"sideNote":["Společný počet sčítá jednotlivé pohyby obou rukou. Nemění se na stejný počet na každou stranu a staré L/R nevykládáme.","The combined count totals individual movements by both hands. It is not converted into that many per side; earlier L/R are not reinterpreted."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"kbsnatch","atlasId":"kbsnatch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3b982da4bf382e6c73bda1c6564609a42634eda532289dff7df5d678470226eb","thumb":"/unified-atlas/kbsnatch-2026edc38744aef1-thumb.webp","detail":"/unified-atlas/kbsnatch-a43ff38d0fcb1a16-detail.webp","inkThumb":"/unified-atlas/kbsnatch-354fc5beb0d30547-inkThumb.webp","inkDetail":"/unified-atlas/kbsnatch-2bb11a5591843b9e-inkDetail.webp","fillThumb":"/unified-atlas/kbsnatch-ad2f81917fb67251-fillThumb.webp","fillDetail":"/unified-atlas/kbsnatch-fccd731880142e9d-fillDetail.webp"},"sourceSha256":"3b982da4bf382e6c73bda1c6564609a42634eda532289dff7df5d678470226eb","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell; prostor pro zášvih a výška nad hlavou","One kettlebell; backswing space and overhead clearance"],"libraryOrders":{"weightlifting":6},"deliveryProfiles":{"f574bb497225d485":{"fields":{"id":"kbsnatch","cz":"Švihový trh kettlebellem","en":"Kettlebell Swing Snatch","pat":"ohyb","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":true,"sideMode":"alternating","focus":["Plynulý přechod ze zášvihu do ustálené natažené paže nad hlavou.","Move continuously from the backswing into a stable straight-arm overhead position."],"startPosition":["Připrav lehký kettlebell před chodidly, volný prostor a výšku nad hlavou. Zpevni kyčelní předklon a uchop madlo jednou rukou. Nácvik příjmu i spouštění proveď s trenérem.","Prepare a light kettlebell ahead of the feet with clear surrounding and overhead space. Brace in a hip hinge and grip with one hand. Practise receiving and lowering with a coach."],"execution":["Ze zášvihu zrychli odrazem kyčlí a veď kettlebell blízko těla. Vsuň ruku do madla a ustal nataženou paži nad hlavou ve stoji. Nacvičeným řízeným návratem spusť kettlebell do zášvihu pro další trh, nebo jej odlož.","Accelerate from the backswing with hip drive and keep the bell close. Insert the hand through the handle and stabilize overhead on a straight arm while standing. Use the practised controlled return to the backswing for another snatch, or park the bell."],"watchFor":["Nahoře se ustal bez dotlačování a bez přepadnutí kettlebellu na předloktí. Paži nenarovnávej násilím přes bolest a bedry nenahrazuj chybějící polohu nad hlavou. Nezvyšuj dávku, pokud se zhoršuje příjem či návrat.","Stabilize without pressing out or letting the bell crash onto the forearm. Do not force the arm straight through pain or compensate with the lower back for the overhead position. Do not increase the dose when receiving or lowering deteriorates."]},"progression":["Švih, přemístění a samotná kontrola nad hlavou mohou připravit dílčí dovednosti. Nejsou časovým ani zátěžovým žebříčkem. Plný trh a jeho návrat posuzuj samostatně s trenérem.","Swings, cleans and overhead control can prepare individual skills. They are not a time or loading ladder. Review the complete snatch and its return separately with a coach."]}}},"ex26_db_snatch":{"id":"ex26_db_snatch","edits":{"cz":"Trh jednoručkou z visu","en":"Hang Dumbbell Snatch","eq":["dumbbell","prostor"],"foc":["Zrychlení jedné jednoručky z visu a příjem na nataženou paži nad hlavou.","Accelerate one dumbbell from the hang and receive on a straight arm overhead."],"pos":["Zvedni lehkou jednoručku do stoje a drž ji mezi stehny. Ustal chodidla a nech volnou dráhu i výšku nad hlavou. Příjem a návrat nejprve nacvič s trenérem.","Lift a light dumbbell to standing and hold it between the thighs. Set the feet and clear the lifting path and overhead space. First practise receiving and lowering with a coach."],"exe":["Krátce se předkloň v kyčlích, pak odrazem nohou a kyčlí veď činku vzhůru blízko těla. Přijmi ji na nataženou paži ve zvládnutém podřepu a úplně se postav. Kontrolovaně vrať činku do visu. Další opakování začíná z visu, ne tahem přímo ze země.","Hinge briefly, then use leg and hip drive to guide the dumbbell upward close to the body. Receive on a straight arm in a controlled dip and stand fully. Lower under control to the hang. The next repetition begins at the hang, not directly from the floor."],"wat":["Nejde o pomalé předpažení ani o přemístění s následným tlakem. Při nejisté opoře nad hlavou nebo bolesti přeruš pokus. Hloubku příjmu zvol předem; historické záznamy neoznačujeme automaticky jako power ani squat snatch.","This is neither a slow front raise nor a clean followed by a press. Stop for an unstable overhead position or pain. Choose receiving depth beforehand; do not automatically relabel historical records as power or squat snatches."],"pro":["Nejdřív nacvič samostatný tah, příjem a spouštění s lehkou činkou. Hmotnost a počet měň ručně podle konkrétního provedení; trh ze země je jiný start.","Practise pulling, receiving and lowering separately with a light dumbbell. Adjust load and repetitions manually according to the specific execution; a floor snatch uses a different start."],"equipmentDetail":["Jedna jednoručka a volný prostor včetně výšky nad hlavou. Jedno přemístění z visu nad hlavu s dokončením ve stoji je jedno opakování na zaznamenanou stranu. Zachovány samostatné L/R dávky a hmotnost použité jednoručky; počty nezdvojujeme.","One dumbbell and clear space including overhead clearance. One lift from the hang to overhead, finished standing, is one repetition on the recorded side. Preserve separate L/R doses and the mass of the dumbbell used; do not double the counts."],"source":{"author":"CrossFit","document":"Dumbbells Training Guide — Snatches, pages18–20","url":"https://assets.crossfit.com/pdfs/seminars/Dumbbell_Training_Guide.pdf","scope":"Published text distinguishes ground/hang and power/squat receiving. PDF illustrations could not be displayed; the existing application still shows only a shallow overhead receive."}},"taxonomy":{"regions":["hips","shoulders"],"secondaryRegions":["thighs","trunk","arms"],"movements":["weightlifting"],"focus":["power","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["dumbbell"],["prostor"]],"aliases":["Trh jednoručkou z visu","Hang Dumbbell Snatch"]},"policy":{"id":"ex26_db_snatch","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["dumbbell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":true,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"single-dumbbell-snatch-per-recorded-side-unknown-legacy-receive-depth","selectionPolicy":"explicit-weightlifting-practice","blockedMotionSources":[],"sideMeaning":["Pracující ruka","Working hand"],"sideNote":["Pro nový plán označ ruku držící náčiní. Jeden úplný pohyb na této ruce je jedno opakování; nejde o dvojnásobek. Význam platí pro nové zadání. Dřívější L/R ani neurčenou stranu nepřeznačujeme.","For a new plan identify the hand holding the implement. One complete movement with that hand is one repetition, without doubling. This meaning applies to a new prescription. Earlier L/R and unspecified sides are not relabelled."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false,"preserveSide":true},"art":{"appId":"ex26_db_snatch","atlasId":"ex26_db_snatch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"02a61dec98753e8b312e0493c0a49e362ec711a2f8edd6a693bb685f8a0cc1fa","thumb":"/expansion-atlas/ex26_db_snatch-original-256.webp","detail":"/expansion-atlas/ex26_db_snatch-original-960.webp","inkThumb":"/expansion-atlas/ex26_db_snatch-ink-256.webp","inkDetail":"/expansion-atlas/ex26_db_snatch-ink-960.webp","fillThumb":"/expansion-atlas/ex26_db_snatch-fill-256.webp","fillDetail":"/expansion-atlas/ex26_db_snatch-fill-960.webp"},"sourceSha256":"02a61dec98753e8b312e0493c0a49e362ec711a2f8edd6a693bb685f8a0cc1fa","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jedna jednoručka; prostor a výška nad hlavou","One dumbbell; surrounding and overhead clearance"],"libraryOrders":{"weightlifting":7},"deliveryProfiles":{"3f360a0ea2b89be9":{"fields":{"id":"ex26_db_snatch","cz":"Trh jednoručkou z visu","en":"Hang Dumbbell Snatch","pat":"ohyb","eq":["dumbbell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":true,"sideMode":"perSide","focus":["Zrychlení jedné jednoručky z visu a příjem na nataženou paži nad hlavou.","Accelerate one dumbbell from the hang and receive on a straight arm overhead."],"startPosition":["Zvedni lehkou jednoručku do stoje a drž ji mezi stehny. Ustal chodidla a nech volnou dráhu i výšku nad hlavou. Příjem a návrat nejprve nacvič s trenérem.","Lift a light dumbbell to standing and hold it between the thighs. Set the feet and clear the lifting path and overhead space. First practise receiving and lowering with a coach."],"execution":["Krátce se předkloň v kyčlích, pak odrazem nohou a kyčlí veď činku vzhůru blízko těla. Přijmi ji na nataženou paži ve zvládnutém podřepu a úplně se postav. Kontrolovaně vrať činku do visu. Další opakování začíná z visu, ne tahem přímo ze země.","Hinge briefly, then use leg and hip drive to guide the dumbbell upward close to the body. Receive on a straight arm in a controlled dip and stand fully. Lower under control to the hang. The next repetition begins at the hang, not directly from the floor."],"watchFor":["Nejde o pomalé předpažení ani o přemístění s následným tlakem. Při nejisté opoře nad hlavou nebo bolesti přeruš pokus. Hloubku příjmu zvol předem; historické záznamy neoznačujeme automaticky jako power ani squat snatch.","This is neither a slow front raise nor a clean followed by a press. Stop for an unstable overhead position or pain. Choose receiving depth beforehand; do not automatically relabel historical records as power or squat snatches."]},"progression":["Nejdřív nacvič samostatný tah, příjem a spouštění s lehkou činkou. Hmotnost a počet měň ručně podle konkrétního provedení; trh ze země je jiný start.","Practise pulling, receiving and lowering separately with a light dumbbell. Adjust load and repetitions manually according to the specific execution; a floor snatch uses a different start."]}}},"kb26_clean_strict_press":{"id":"kb26_clean_strict_press","edits":{"eq":["kettlebell","prostor"],"foc":["Přemístění jednoho kettlebellu a navazující tlak bez odrazu nohou.","Clean one kettlebell and follow with a press without leg drive."],"pos":["Připrav lehký kettlebell, volný prostor pro zášvih a dostatečnou výšku nad hlavou. Nejprve zvládni přemístění a striktní tlak samostatně.","Prepare a light kettlebell, backswing clearance and enough overhead space. First learn the clean and strict press separately."],"exe":["Přemísti kettlebell ze zášvihu k rameni a ustal jej. Bez pokrčení kolen a odrazu nohou jej vytlač nad hlavu, poté kontrolovaně vrať k rameni. Pro další opakování proveď nové přemístění; po sérii závaží odlož.","Clean the kettlebell from a backswing to the shoulder and settle it. Press overhead without dipping the knees or driving with the legs, then lower under control to the rack. Perform a new clean for the next repetition; park the bell after the set."],"wat":["Tlak nezachraňuj záklonem ani pohybem nohou. Pokud se bez nich neobejdeš, sniž zátěž nebo cvič části zvlášť. Kettlebell při přemístění nemá narážet do předloktí.","Do not rescue the press by leaning back or driving with the legs. If these are needed, reduce the load or practise the parts separately. Avoid forearm impact during the clean."],"pro":["Náročnost upravuj ručně podle klidného příjmu a kontrolovaného tlaku. Čisté provedení jednou rukou neznamená automatickou připravenost na pár.","Adjust difficulty manually according to a calm receive and controlled press. A controlled single-arm version does not automatically establish readiness for a pair."],"equipmentDetail":["Jeden kettlebell; volný prostor pro zášvih a nad hlavou. Jeden celý cyklus přemístění, tlak a návrat je jedno opakování na zapsanou stranu. Kg jsou hmotnost použitého kettlebellu; původní L/R a dávky zachováváme.","One kettlebell; backswing and overhead clearance. One complete clean, press and return counts as one repetition on the recorded side. Kilograms are the mass of the bell used; earlier L/R records and doses are preserved."],"source":{"author":"Josh Bryant / ISSA","document":"6-Week Kettlebell Training — Exercise 3, page9","url":"https://assets.ctfassets.net/qw8ps43tg2ux/28pDkAfaoJnEm1xIvClOgn/9de10740d0f9fd95666f4a2e9d9c9adb/issa-ebook-6-week-kettlebell-training.pdf","scope":"Published text supports a clean, rack, press and reverse-clean cycle. Nuffield Health distinguishes strict press from push press; the original Onnit video was not available for playback."}},"taxonomy":{"regions":["shoulders","hips"],"secondaryRegions":["arms","trunk","thighs"],"movements":["weightlifting","push_vertical"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Přemístění kettlebellu a striktní tlak","Kettlebell Clean and Strict Press"]},"policy":{"id":"kb26_clean_strict_press","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"single-bell-whole-clean-strict-press-cycle-per-recorded-side","selectionPolicy":"explicit-combined-clean-strict-press-practice","blockedMotionSources":[],"sideMeaning":["Pracující ruka","Working hand"],"sideNote":["Pro nový plán označ ruku držící náčiní. Jeden úplný pohyb na této ruce je jedno opakování; nejde o dvojnásobek. Význam platí pro nové zadání. Dřívější L/R ani neurčenou stranu nepřeznačujeme.","For a new plan identify the hand holding the implement. One complete movement with that hand is one repetition, without doubling. This meaning applies to a new prescription. Earlier L/R and unspecified sides are not relabelled."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false,"preserveSide":true},"art":{"appId":"kb26_clean_strict_press","atlasId":"kb26_clean_strict_press","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"784b4e13cbe7c9401d5ff7cb0e3ab1a946db33b7f55510dd28b3fd837f0d7f11","thumb":"/expansion-atlas/kb26_clean_strict_press-original-256.webp","detail":"/expansion-atlas/kb26_clean_strict_press-original-960.webp","inkThumb":"/expansion-atlas/kb26_clean_strict_press-ink-256.webp","inkDetail":"/expansion-atlas/kb26_clean_strict_press-ink-960.webp","fillThumb":"/expansion-atlas/kb26_clean_strict_press-fill-256.webp","fillDetail":"/expansion-atlas/kb26_clean_strict_press-fill-960.webp"},"sourceSha256":"784b4e13cbe7c9401d5ff7cb0e3ab1a946db33b7f55510dd28b3fd837f0d7f11","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell; prostor pro zášvih a nad hlavou","One kettlebell; backswing and overhead clearance"],"libraryOrders":{"weightlifting":4},"deliveryProfiles":{"7f182140f1677eb0":{"fields":{"id":"kb26_clean_strict_press","cz":"Přemístění kettlebellu a striktní tlak","en":"Kettlebell Clean and Strict Press","pat":"tlak","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":true,"sideMode":"perSide","focus":["Přemístění jednoho kettlebellu a navazující tlak bez odrazu nohou.","Clean one kettlebell and follow with a press without leg drive."],"startPosition":["Připrav lehký kettlebell, volný prostor pro zášvih a dostatečnou výšku nad hlavou. Nejprve zvládni přemístění a striktní tlak samostatně.","Prepare a light kettlebell, backswing clearance and enough overhead space. First learn the clean and strict press separately."],"execution":["Přemísti kettlebell ze zášvihu k rameni a ustal jej. Bez pokrčení kolen a odrazu nohou jej vytlač nad hlavu, poté kontrolovaně vrať k rameni. Pro další opakování proveď nové přemístění; po sérii závaží odlož.","Clean the kettlebell from a backswing to the shoulder and settle it. Press overhead without dipping the knees or driving with the legs, then lower under control to the rack. Perform a new clean for the next repetition; park the bell after the set."],"watchFor":["Tlak nezachraňuj záklonem ani pohybem nohou. Pokud se bez nich neobejdeš, sniž zátěž nebo cvič části zvlášť. Kettlebell při přemístění nemá narážet do předloktí.","Do not rescue the press by leaning back or driving with the legs. If these are needed, reduce the load or practise the parts separately. Avoid forearm impact during the clean."]},"progression":["Náročnost upravuj ručně podle klidného příjmu a kontrolovaného tlaku. Čisté provedení jednou rukou neznamená automatickou připravenost na pár.","Adjust difficulty manually according to a calm receive and controlled press. A controlled single-arm version does not automatically establish readiness for a pair."]}}},"kb26_double_clean_press":{"id":"kb26_double_clean_press","edits":{"eq":["kettlebell_pair","prostor"],"foc":["Současné přemístění dvou kettlebellů a striktní tlak oběma pažemi.","Clean two kettlebells together and follow with a strict press using both arms."],"pos":["Připrav dva lehké kettlebelly stejné hmotnosti. Zvol postoj s místem pro jejich průchod mezi stehny a ověř volný prostor nad hlavou. Přemístění páru i tlak nejprve zvládni samostatně.","Prepare two light kettlebells of the same mass. Use a stance that leaves room for both bells between the thighs and check overhead clearance. First learn the double clean and double press separately."],"exe":["Ze zášvihu přemísti obě závaží k ramenům a ustal je. Bez podřepu a odrazu nohou je současně vytlač nad hlavu. Kontrolovaně je vrať k ramenům a před dalším tlakem znovu přemísti ze zášvihu. Na konci pár odlož.","Clean both bells from the backswing to the shoulders and settle them. Press them overhead together without a dip or leg drive. Lower under control to the rack and perform another clean from the backswing before the next press. Park the pair at the end."],"wat":["Nenahrazuj striktní tlak výtlačným odrazem. Vyhni se výraznému záklonu; pokud obě závaží nedokážeš zvednout a vrátit pod kontrolou, ukonči sérii a uprav zátěž.","Do not replace the strict press with a push press. Avoid a pronounced backward lean; if both bells cannot be raised and returned under control, end the set and adjust the load."],"pro":["Pár mění průchod závaží i nároky na ustálení. Zátěž zvol samostatně, ne jako automatický dvojnásobek jednoruční varianty. Přesnost a samostatně zvládnuté části mají přednost před přidáváním kg.","A pair changes clearance and stabilization demands. Choose its load separately, not as an automatic doubling of the single-arm version. Prioritize control and independently learned parts before adding kilograms."],"equipmentDetail":["Dva kettlebelly a volný prostor včetně výšky. Jeden současný cyklus páru je jedno opakování bez L/R sad. Pro nový záznam kg použij součet obou kusů a jejich jednotlivé hmotnosti uveď v poznámce. Staré kg s neurčenou konvencí kus/pár zachováváme bez přepočtu a bez porovnávání.","Two kettlebells and clear space including overhead height. One simultaneous cycle of the pair is one repetition without L/R sets. For a new kilogram record use their combined mass and note the individual masses. Earlier kilograms with an unknown per-bell/pair convention are preserved without conversion or comparison."],"source":{"author":"Onnit Academy","document":"6 Kettlebell Exercises to Build Muscle — Double Clean and Press","url":"https://www.onnit.com/blogs/the-edge/6-kettlebell-exercises-to-build-muscle","scope":"Confirms the double clean-and-press identity. Strict pressing is separately distinguished by Nuffield Health; this audit preserves the existing no-leg-drive variant and repeated-clean cycle, without adopting the source workout or performance claims."}},"taxonomy":{"regions":["shoulders","hips"],"secondaryRegions":["arms","trunk","thighs"],"movements":["weightlifting","push_vertical"],"focus":["strength","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell_pair"],["prostor"]],"aliases":["Přemístění dvou kettlebellů a striktní tlak","Double-Kettlebell Clean and Strict Press"]},"policy":{"id":"kb26_double_clean_press","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["kettlebell_pair"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-pair-whole-clean-strict-press-cycle-new-total-mass-historical-convention-unknown","selectionPolicy":"explicit-combined-clean-strict-press-practice","blockedMotionSources":[],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false},"art":{"appId":"kb26_double_clean_press","atlasId":"kb26_double_clean_press","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"55756f38a18a3c32f3d45b4cbc0005e7217d12ed91e268bf02350783813dc5b9","thumb":"/expansion-atlas/kb26_double_clean_press-original-256.webp","detail":"/expansion-atlas/kb26_double_clean_press-original-960.webp","inkThumb":"/expansion-atlas/kb26_double_clean_press-ink-256.webp","inkDetail":"/expansion-atlas/kb26_double_clean_press-ink-960.webp","fillThumb":"/expansion-atlas/kb26_double_clean_press-fill-256.webp","fillDetail":"/expansion-atlas/kb26_double_clean_press-fill-960.webp"},"sourceSha256":"55756f38a18a3c32f3d45b4cbc0005e7217d12ed91e268bf02350783813dc5b9","contourOnly":true,"darkOutline":true},"equipmentLabels":["Dva kettlebelly; prostor pro průchod a nad hlavou","Two kettlebells; passage and overhead clearance"],"libraryOrders":{"weightlifting":5},"deliveryProfiles":{"ca26284e9093b524":{"fields":{"id":"kb26_double_clean_press","cz":"Přemístění dvou kettlebellů a striktní tlak","en":"Double-Kettlebell Clean and Strict Press","pat":"tlak","eq":["kettlebell_pair","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":150,"unilateral":false,"sideMode":"none","focus":["Současné přemístění dvou kettlebellů a striktní tlak oběma pažemi.","Clean two kettlebells together and follow with a strict press using both arms."],"startPosition":["Připrav dva lehké kettlebelly stejné hmotnosti. Zvol postoj s místem pro jejich průchod mezi stehny a ověř volný prostor nad hlavou. Přemístění páru i tlak nejprve zvládni samostatně.","Prepare two light kettlebells of the same mass. Use a stance that leaves room for both bells between the thighs and check overhead clearance. First learn the double clean and double press separately."],"execution":["Ze zášvihu přemísti obě závaží k ramenům a ustal je. Bez podřepu a odrazu nohou je současně vytlač nad hlavu. Kontrolovaně je vrať k ramenům a před dalším tlakem znovu přemísti ze zášvihu. Na konci pár odlož.","Clean both bells from the backswing to the shoulders and settle them. Press them overhead together without a dip or leg drive. Lower under control to the rack and perform another clean from the backswing before the next press. Park the pair at the end."],"watchFor":["Nenahrazuj striktní tlak výtlačným odrazem. Vyhni se výraznému záklonu; pokud obě závaží nedokážeš zvednout a vrátit pod kontrolou, ukonči sérii a uprav zátěž.","Do not replace the strict press with a push press. Avoid a pronounced backward lean; if both bells cannot be raised and returned under control, end the set and adjust the load."]},"progression":["Pár mění průchod závaží i nároky na ustálení. Zátěž zvol samostatně, ne jako automatický dvojnásobek jednoruční varianty. Přesnost a samostatně zvládnuté části mají přednost před přidáváním kg.","A pair changes clearance and stabilization demands. Choose its load separately, not as an automatic doubling of the single-arm version. Prioritize control and independently learned parts before adding kilograms."]}}},"ex26_kb_windmill":{"id":"ex26_kb_windmill","edits":{"cz":"Větrný mlýn s kettlebellem nad hlavou","en":"Overhead Kettlebell Windmill","eq":["kettlebell","prostor"],"foc":["Kontrolovaný šikmý předklon v kyčlích se stabilním kettlebellem nad ramenem.","A controlled oblique hip hinge with the kettlebell stable above the shoulder."],"pos":["Ustal lehký kettlebell nad ramenem a natoč chodidla mírně od zatížené strany. Postoj musí umožnit posun kyčle dozadu; nejprve jej vyzkoušej bez zátěže.","Stabilize a light kettlebell above the shoulder and turn the feet slightly away from the loaded side. The stance must allow the hip to shift back; first practise unloaded."],"exe":["Posuň kyčel pod kettlebellem šikmo dozadu. S dlouhým trupem a mírným otevřením hrudníku veď volnou ruku podél vnitřní strany přední nohy. Horní paži udrž svisle a vrať se do stoje.","Shift the hip beneath the kettlebell diagonally back. Keep the trunk long and allow a small chest turn as the free hand follows the inner front leg. Maintain the upper arm vertically and return to standing."],"wat":["Nejde o hluboký úklon v bedrech ani honbu za dotykem země. Rozsah zkrať, pokud ztrácíš oporu ramene nebo kontrolu trupu. Nepokračuj do únavového selhání.","This is not a deep lumbar side bend or a test of touching the floor. Shorten the range if shoulder support or trunk control is lost. Avoid practising to fatigue failure."],"pro":["Začni krátkým pohybem bez závaží. Dolní držení zátěže má jiné nároky; přechod nad hlavu se vybírá záměrně, nikoli automaticky podle počtu opakování.","Begin with a short unloaded motion. A low-held load has different demands; choose overhead loading deliberately, not automatically from repetition counts."],"equipmentDetail":["Jeden kettlebell; místo pro postoj, pohyb a nadhlavní držení. Jeden předklon a návrat je jedno opakování. Pro nové L/R zadání označ stranu ruky s kettlebellem; staré názvy stran a dávky se nemění. Kg jsou hmotnost jednoho kusu.","One kettlebell; stance, movement and overhead clearance. One hinge and return is one repetition. In new L/R prescriptions name the hand holding the bell; earlier side labels and doses remain unchanged. Kilograms refer to one bell."],"source":{"author":"Brett Jones / StrongFirst","document":"Kettlebell Windmill101","url":"https://www.strongfirst.com/kettlebell-windmill-101/","scope":"Technical text supports an oblique hip shift and controlled trunk, not lumbar lateral flexion. Stance is individualized; numerical distribution and programme are not imported."}},"taxonomy":{"regions":["hips","trunk"],"secondaryRegions":["thighs","shoulders"],"movements":["hinge","trunk_movement"],"focus":["mobility","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Větrný mlýn s kettlebellem","Kettlebell Windmill"]},"policy":{"id":"ex26_kb_windmill","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-controlled-windmill-return-per-recorded-side-no-historical-side-relabel","selectionPolicy":"explicit-loaded-mobility-practice","blockedMotionSources":[],"sideMeaning":["Paže se zátěží nad hlavou","Overhead loaded arm"],"sideNote":["Pro nový zápis L/R označuje paži držící kettlebell nad hlavou, nikoli směr předklonu ani dolní ruku. Význam platí pro nové zadání. Dřívější L/R ani neurčenou stranu nepřeznačujeme.","For a new record L/R identifies the arm holding the kettlebell overhead, not the bend direction or lower hand. This meaning applies to a new prescription. Earlier L/R and unspecified sides are not relabelled."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false,"preserveSide":true},"art":{"appId":"ex26_kb_windmill","atlasId":"ex26_kb_windmill","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"78f4ffaf0038cd1add1aec5ae53e02c5d381806591f53045493c15053befe9c5","thumb":"/expansion-atlas/ex26_kb_windmill-original-256.webp","detail":"/expansion-atlas/ex26_kb_windmill-original-960.webp","inkThumb":"/expansion-atlas/ex26_kb_windmill-ink-256.webp","inkDetail":"/expansion-atlas/ex26_kb_windmill-ink-960.webp","fillThumb":"/expansion-atlas/ex26_kb_windmill-fill-256.webp","fillDetail":"/expansion-atlas/ex26_kb_windmill-fill-960.webp"},"sourceSha256":"78f4ffaf0038cd1add1aec5ae53e02c5d381806591f53045493c15053befe9c5","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell nad hlavou; volný prostor","One overhead kettlebell; clear space"],"libraryOrders":{"hinge":1},"deliveryProfiles":{"e3ad984fc2e21b82":{"fields":{"id":"ex26_kb_windmill","cz":"Větrný mlýn s kettlebellem nad hlavou","en":"Overhead Kettlebell Windmill","pat":"ohyb","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":true,"sideMode":"perSide","focus":["Kontrolovaný šikmý předklon v kyčlích se stabilním kettlebellem nad ramenem.","A controlled oblique hip hinge with the kettlebell stable above the shoulder."],"startPosition":["Ustal lehký kettlebell nad ramenem a natoč chodidla mírně od zatížené strany. Postoj musí umožnit posun kyčle dozadu; nejprve jej vyzkoušej bez zátěže.","Stabilize a light kettlebell above the shoulder and turn the feet slightly away from the loaded side. The stance must allow the hip to shift back; first practise unloaded."],"execution":["Posuň kyčel pod kettlebellem šikmo dozadu. S dlouhým trupem a mírným otevřením hrudníku veď volnou ruku podél vnitřní strany přední nohy. Horní paži udrž svisle a vrať se do stoje.","Shift the hip beneath the kettlebell diagonally back. Keep the trunk long and allow a small chest turn as the free hand follows the inner front leg. Maintain the upper arm vertically and return to standing."],"watchFor":["Nejde o hluboký úklon v bedrech ani honbu za dotykem země. Rozsah zkrať, pokud ztrácíš oporu ramene nebo kontrolu trupu. Nepokračuj do únavového selhání.","This is not a deep lumbar side bend or a test of touching the floor. Shorten the range if shoulder support or trunk control is lost. Avoid practising to fatigue failure."]},"progression":["Začni krátkým pohybem bez závaží. Dolní držení zátěže má jiné nároky; přechod nad hlavu se vybírá záměrně, nikoli automaticky podle počtu opakování.","Begin with a short unloaded motion. A low-held load has different demands; choose overhead loading deliberately, not automatically from repetition counts."]}}},"ex26_kb_lowwindmill":{"id":"ex26_kb_lowwindmill","edits":{"eq":["kettlebell","prostor"],"foc":["Kontrolovaný šikmý předklon s kettlebellem ve spodní ruce.","A controlled oblique hip hinge with the kettlebell in the lower hand."],"pos":["Zvol stabilní širší postoj. Lehký kettlebell drž vedle stehna ve spodní ruce a druhou paži zvedni. Zkontroluj místo pro závaží i volnou paži.","Use a stable wider stance. Hold a light kettlebell beside the thigh in the lower hand and raise the other arm. Check clearance for the bell and free arm."],"exe":["Pohyb veď z kyčlí a pomalu spusť kettlebell podél vnitřní strany bližší nohy. Hrudník se přiměřeně otevře vzhůru, trup zůstává dlouhý. Bez švihu se narovnej.","Move through the hips and slowly lower the bell along the inner near leg. Let the chest turn upward within control while keeping the trunk long. Rise without swinging."],"wat":["Zátěž tě nesmí táhnout za kontrolovaný rozsah; dotyk země není podmínkou. Nezaměňuj pohyb kyčlí za hluboký bederní úklon. Pohled vzhůru nevynucuj, pokud působí potíže.","Do not let the load pull beyond controlled range; touching the floor is optional. Avoid substituting a deep lumbar side bend for hip movement. Do not force an upward gaze if uncomfortable."],"pro":["Nejprve nacvič krátký pohyb bez zátěže. Hmotnost a rozsah upravuj ručně; spodní držení není automatickou zárukou vhodnosti ani povinným stupněm k nadhlavní variantě.","First practise a short unloaded movement. Adjust load and range manually; low loading is neither an automatic guarantee of suitability nor a mandatory step toward the overhead version."],"equipmentDetail":["Jeden kettlebell a prostor. Jeden předklon a návrat je jedno opakování na zapsanou stranu; v novém zadání uveď ruku se závažím dole. Historické L/R nepřekládáme na opačnou horní ruku. Kg jsou hmotnost jednoho kusu.","One kettlebell and clear space. One hinge and return is one repetition on the recorded side; in new prescriptions specify the lower loaded hand. Do not relabel historical L/R as the opposite raised hand. Kilograms refer to one bell."]},"taxonomy":{"regions":["hips","trunk"],"secondaryRegions":["thighs","shoulders"],"movements":["hinge","trunk_movement"],"focus":["mobility","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["kettlebell"],["prostor"]],"aliases":["Větrný mlýn s kettlebellem v dolní ruce","Low Kettlebell Windmill"]},"policy":{"id":"ex26_kb_lowwindmill","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["kettlebell"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-controlled-windmill-return-per-recorded-side-no-historical-side-relabel","selectionPolicy":"explicit-loaded-mobility-practice","blockedMotionSources":[],"sideMeaning":["Dolní ruka se zátěží","Lower loaded hand"],"sideNote":["Pro nový zápis L/R označuje dolní ruku držící kettlebell, nikoli paži nad hlavou. Význam platí pro nové zadání. Dřívější L/R ani neurčenou stranu nepřeznačujeme.","For a new record L/R identifies the lower hand holding the kettlebell, not the overhead arm. This meaning applies to a new prescription. Earlier L/R and unspecified sides are not relabelled."],"noAddedWeight":false,"allowCopyCompletedAcrossSides":false,"preserveSide":true},"art":{"appId":"ex26_kb_lowwindmill","atlasId":"ex26_kb_lowwindmill","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"391f7e24ca1057eb0cdaa502a9b2f61b18ef2d403bf54a9ad443ccb577ac3d42","thumb":"/expansion-atlas/ex26_kb_lowwindmill-original-256.webp","detail":"/expansion-atlas/ex26_kb_lowwindmill-original-960.webp","inkThumb":"/expansion-atlas/ex26_kb_lowwindmill-ink-256.webp","inkDetail":"/expansion-atlas/ex26_kb_lowwindmill-ink-960.webp","fillThumb":"/expansion-atlas/ex26_kb_lowwindmill-fill-256.webp","fillDetail":"/expansion-atlas/ex26_kb_lowwindmill-fill-960.webp"},"sourceSha256":"391f7e24ca1057eb0cdaa502a9b2f61b18ef2d403bf54a9ad443ccb577ac3d42","contourOnly":true,"darkOutline":true},"equipmentLabels":["Jeden kettlebell v dolní ruce; volný prostor","One kettlebell in the lower hand; clear space"],"libraryOrders":{"hinge":0},"deliveryProfiles":{"9f16384848f2924f":{"fields":{"id":"ex26_kb_lowwindmill","cz":"Větrný mlýn s kettlebellem v dolní ruce","en":"Low Kettlebell Windmill","pat":"ohyb","eq":["kettlebell","prostor"],"measurementType":"WEIGHT_REPS","defaultRestSec":120,"unilateral":true,"sideMode":"perSide","focus":["Kontrolovaný šikmý předklon s kettlebellem ve spodní ruce.","A controlled oblique hip hinge with the kettlebell in the lower hand."],"startPosition":["Zvol stabilní širší postoj. Lehký kettlebell drž vedle stehna ve spodní ruce a druhou paži zvedni. Zkontroluj místo pro závaží i volnou paži.","Use a stable wider stance. Hold a light kettlebell beside the thigh in the lower hand and raise the other arm. Check clearance for the bell and free arm."],"execution":["Pohyb veď z kyčlí a pomalu spusť kettlebell podél vnitřní strany bližší nohy. Hrudník se přiměřeně otevře vzhůru, trup zůstává dlouhý. Bez švihu se narovnej.","Move through the hips and slowly lower the bell along the inner near leg. Let the chest turn upward within control while keeping the trunk long. Rise without swinging."],"watchFor":["Zátěž tě nesmí táhnout za kontrolovaný rozsah; dotyk země není podmínkou. Nezaměňuj pohyb kyčlí za hluboký bederní úklon. Pohled vzhůru nevynucuj, pokud působí potíže.","Do not let the load pull beyond controlled range; touching the floor is optional. Avoid substituting a deep lumbar side bend for hip movement. Do not force an upward gaze if uncomfortable."]},"progression":["Nejprve nacvič krátký pohyb bez zátěže. Hmotnost a rozsah upravuj ručně; spodní držení není automatickou zárukou vhodnosti ani povinným stupněm k nadhlavní variantě.","First practise a short unloaded movement. Adjust load and range manually; low loading is neither an automatic guarantee of suitability nor a mandatory step toward the overhead version."]}}},"battlerope":{"id":"battlerope","edits":{"cz":"Svislé vlny bojovým lanem","en":"Vertical Battle-Rope Waves","eq":["lano","prostor","rope_anchor"],"measurementType":"DURATION","load":"none","foc":["Plynulé svislé vlny pohybem paží s oporou celého těla.","Continuous vertical waves driven by the arms with whole-body support."],"pos":["Zkontroluj bojové lano, držadla a kotvení určené pro tento úkol podle návodu výrobce. Nech volnou celou dráhu lana. Uchop jeden konec do každé ruky, mírně pokrč kyčle a kolena a ustal postoj; lano netahej do úplného napnutí.","Check the battle rope, handles and an anchor intended for this task according to the manufacturer instructions. Clear the full rope path. Hold one end in each hand, soften hips and knees and establish a stable stance; avoid pulling the rope completely taut."],"exe":["Pohybuj rukama nahoru a dolů střídavě, nebo současně podle zadání. Posílej vlny podél lana ke kotvě a udrž kontrolovaný rytmus. V rámci úseku používej zvolený způsob; změnu si poznamenej.","Move the hands up and down alternately or together as prescribed. Send waves along the rope toward its anchor with controlled rhythm. Keep the selected pattern within the interval and note any change."],"wat":["Vlna nevychází výhradně z kyčlí: pracují paže a tělo jim poskytuje oporu. Netrhej pouze zády a neprotahuj úsek přes ztrátu kontroly. Při uvolnění kotvy ihned přestaň.","The wave does not originate only from the hips: the arms move while the body supports them. Avoid heaving only through the back or extending an interval beyond control. Stop immediately if the anchor loosens."],"pro":["Začni menšími vlnami a krátkým zvládnutelným úsekem. Délku, rytmus či lano měň vědomě, ne všechny současně. Maximální rychlost není povinná.","Begin with smaller waves and a manageable short interval. Adjust duration, rhythm or rope deliberately, not all at once. Maximum speed is not required."],"equipmentDetail":["Zapisuj sekundy celého pracovního úseku pro obě ruce společně, nikoli počet vln nebo čas každé ruky zvlášť. Původní časy se nemění. Typ lana, rytmus a velikost vln můžeš poznamenat; samotný delší čas neznamená srovnatelně lepší výkon.","Record seconds for the whole work interval with both hands together, not wave counts or separate arm times. Earlier durations remain unchanged. You may note the rope, rhythm and wave size; a longer duration alone is not a comparable performance improvement."],"source":{"author":"Ingrid Marcum / ACE Certified","document":"Branch Out With Strength Equipment — Battle Ropes","url":"https://www.acefitness.org/continuing-education/certified/june-2018/7010/branch-out-with-strength-equipment/","scope":"Primary instructor explanation of rope slack, wave travel and alternating arm action; retains existing simultaneous option without importing programme durations."}},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["trunk","arms","forearms_hands"],"movements":["rope_waves"],"focus":["conditioning","coordination"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["lano"],["prostor"],["rope_anchor"]],"aliases":["Bojové lano","Battle Ropes"]},"policy":{"id":"battlerope","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["lano"],["prostor"],["rope_anchor"]],"unknown":false,"explicitTarget":false,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-bilateral-rope-work-interval-no-wave-count-or-historical-conversion","selectionPolicy":"existing-conditioning-selection-exact-anchored-rope","blockedMotionSources":[],"sideNote":["Čas patří celému obouručnímu úseku, i když paže pracují střídavě. Není to čas na každou stranu ani počet vln.","Time covers the whole two-arm interval, even when the arms alternate. It is not time per side or a wave count."],"noAddedWeight":true,"allowCopyCompletedAcrossSides":false},"art":{"appId":"battlerope","atlasId":"battlerope","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"23bd75a4bcf1020f0986d3a752e5bc0742c3a0e58f56da3f655be818f9ef71fd","thumb":"/unified-atlas/battlerope-b979ce8497fa11cf-thumb.webp","detail":"/unified-atlas/battlerope-300b429acf0223b5-detail.webp","inkThumb":"/unified-atlas/battlerope-059be88bc9206f5c-inkThumb.webp","inkDetail":"/unified-atlas/battlerope-06c78ce9201b370a-inkDetail.webp","fillThumb":"/unified-atlas/battlerope-593ffd5fd7f9672e-fillThumb.webp","fillDetail":"/unified-atlas/battlerope-1fe2c2b2ea67740f-fillDetail.webp"},"sourceSha256":"23bd75a4bcf1020f0986d3a752e5bc0742c3a0e58f56da3f655be818f9ef71fd","contourOnly":true,"darkOutline":true},"equipmentLabels":["Bojové lano, odpovídající kotva a volná dráha lana","Battle rope, suitable anchor and clear rope path"],"libraryOrders":{"rope_waves":0},"deliveryProfiles":{"f3f4a3a49a05f295":{"fields":{"id":"battlerope","cz":"Svislé vlny bojovým lanem","en":"Vertical Battle-Rope Waves","pat":"prenos","eq":["lano","prostor","rope_anchor"],"measurementType":"DURATION","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Plynulé svislé vlny pohybem paží s oporou celého těla.","Continuous vertical waves driven by the arms with whole-body support."],"startPosition":["Zkontroluj bojové lano, držadla a kotvení určené pro tento úkol podle návodu výrobce. Nech volnou celou dráhu lana. Uchop jeden konec do každé ruky, mírně pokrč kyčle a kolena a ustal postoj; lano netahej do úplného napnutí.","Check the battle rope, handles and an anchor intended for this task according to the manufacturer instructions. Clear the full rope path. Hold one end in each hand, soften hips and knees and establish a stable stance; avoid pulling the rope completely taut."],"execution":["Pohybuj rukama nahoru a dolů střídavě, nebo současně podle zadání. Posílej vlny podél lana ke kotvě a udrž kontrolovaný rytmus. V rámci úseku používej zvolený způsob; změnu si poznamenej.","Move the hands up and down alternately or together as prescribed. Send waves along the rope toward its anchor with controlled rhythm. Keep the selected pattern within the interval and note any change."],"watchFor":["Vlna nevychází výhradně z kyčlí: pracují paže a tělo jim poskytuje oporu. Netrhej pouze zády a neprotahuj úsek přes ztrátu kontroly. Při uvolnění kotvy ihned přestaň.","The wave does not originate only from the hips: the arms move while the body supports them. Avoid heaving only through the back or extending an interval beyond control. Stop immediately if the anchor loosens."]},"progression":["Začni menšími vlnami a krátkým zvládnutelným úsekem. Délku, rytmus či lano měň vědomě, ne všechny současně. Maximální rychlost není povinná.","Begin with smaller waves and a manageable short interval. Adjust duration, rhythm or rope deliberately, not all at once. Maximum speed is not required."]}}},"ex26_rope_lateral":{"id":"ex26_rope_lateral","edits":{"eq":["lano","prostor","rope_anchor"],"pos":["Zkontroluj bojové lano, držadla a kotvení určené pro tento úkol podle návodu výrobce. Nech volnou celou dráhu lana. Uchop jeden konec do každé ruky, mírně pokrč kyčle a kolena a ustal postoj; lano netahej do úplného napnutí.","Check the battle rope, handles and an anchor intended for this task according to the manufacturer instructions. Clear the full rope path. Hold one end in each hand, soften hips and knees and establish a stable stance; avoid pulling the rope completely taut."],"foc":["Boční vlny oběma konci lana při kontrolovaném pohybu celého těla.","Side-to-side waves with both rope ends and controlled whole-body movement."],"exe":["Veď oba konce společně do strany a zpět, aby se vodorovné vlny šířily po zemi ke kotvě. Paže, hrudník a kyčle se mohou plynule zapojit do pohybu.","Sweep both ends together from side to side, sending horizontal waves along the floor toward the anchor. Allow the arms, chest and hips to contribute smoothly."],"wat":["Netvoř boční švih pouze bedry ani prudkým kroucením kolen. Zmenši pohyb, pokud ztrácíš postoj nebo pevné držení. Při pohybu kotvy skonči.","Avoid creating the sweep only through the lower back or abrupt knee twisting. Reduce the motion if stance or grip is lost. Stop if the anchor moves."],"pro":["Menší boční vlny a kratší úsek usnadní kontrolu. Rozsah a rytmus měň ručně; není nutné přidávat výpad ani skok.","Smaller lateral waves and a shorter interval make control easier. Adjust range and rhythm manually; a lunge or jump is not required."],"equipmentDetail":["Zapisuj sekundy celého pracovního úseku pro obě ruce společně, nikoli počet vln nebo čas každé ruky zvlášť. Původní časy se nemění. Typ lana, rytmus a velikost vln můžeš poznamenat; samotný delší čas neznamená srovnatelně lepší výkon.","Record seconds for the whole work interval with both hands together, not wave counts or separate arm times. Earlier durations remain unchanged. You may note the rope, rhythm and wave size; a longer duration alone is not a comparable performance improvement."]},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["trunk","arms","forearms_hands"],"movements":["rope_waves"],"focus":["conditioning","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["lano"],["prostor"],["rope_anchor"]],"aliases":["Boční vlny bojovým lanem","Lateral Battle-Rope Waves"]},"policy":{"id":"ex26_rope_lateral","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["lano"],["prostor"],["rope_anchor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-bilateral-rope-work-interval-no-wave-count-or-historical-conversion","selectionPolicy":"explicit-rope-wave-variation","blockedMotionSources":[],"sideNote":["Čas patří celému obouručnímu úseku, ne samostatné levé či pravé vlně.","Time covers the whole two-arm interval, not an individual left or right wave."],"noAddedWeight":true,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_rope_lateral","atlasId":"ex26_rope_lateral","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"159ed7d0bc85602b736e3d5d0786c94bc5f709b4cc2534838a524bc2088b2fb6","thumb":"/expansion-atlas/ex26_rope_lateral-audit20261013-original-256.webp","detail":"/expansion-atlas/ex26_rope_lateral-audit20261013-original-960.webp","inkThumb":"/expansion-atlas/ex26_rope_lateral-audit20261013-ink-256.webp","inkDetail":"/expansion-atlas/ex26_rope_lateral-audit20261013-ink-960.webp","fillThumb":"/expansion-atlas/ex26_rope_lateral-audit20261013-fill-256.webp","fillDetail":"/expansion-atlas/ex26_rope_lateral-audit20261013-fill-960.webp"},"sourceSha256":"159ed7d0bc85602b736e3d5d0786c94bc5f709b4cc2534838a524bc2088b2fb6","contourOnly":true,"darkOutline":true},"equipmentLabels":["Bojové lano, odpovídající kotva a volná dráha lana","Battle rope, suitable anchor and clear rope path"],"libraryOrders":{"rope_waves":1},"deliveryProfiles":{"522c374d5139c63f":{"fields":{"id":"ex26_rope_lateral","cz":"Boční vlny bojovým lanem","en":"Lateral Battle-Rope Waves","pat":"stred","eq":["lano","prostor","rope_anchor"],"measurementType":"DURATION","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Boční vlny oběma konci lana při kontrolovaném pohybu celého těla.","Side-to-side waves with both rope ends and controlled whole-body movement."],"startPosition":["Zkontroluj bojové lano, držadla a kotvení určené pro tento úkol podle návodu výrobce. Nech volnou celou dráhu lana. Uchop jeden konec do každé ruky, mírně pokrč kyčle a kolena a ustal postoj; lano netahej do úplného napnutí.","Check the battle rope, handles and an anchor intended for this task according to the manufacturer instructions. Clear the full rope path. Hold one end in each hand, soften hips and knees and establish a stable stance; avoid pulling the rope completely taut."],"execution":["Veď oba konce společně do strany a zpět, aby se vodorovné vlny šířily po zemi ke kotvě. Paže, hrudník a kyčle se mohou plynule zapojit do pohybu.","Sweep both ends together from side to side, sending horizontal waves along the floor toward the anchor. Allow the arms, chest and hips to contribute smoothly."],"watchFor":["Netvoř boční švih pouze bedry ani prudkým kroucením kolen. Zmenši pohyb, pokud ztrácíš postoj nebo pevné držení. Při pohybu kotvy skonči.","Avoid creating the sweep only through the lower back or abrupt knee twisting. Reduce the motion if stance or grip is lost. Stop if the anchor moves."]},"progression":["Menší boční vlny a kratší úsek usnadní kontrolu. Rozsah a rytmus měň ručně; není nutné přidávat výpad ani skok.","Smaller lateral waves and a shorter interval make control easier. Adjust range and rhythm manually; a lunge or jump is not required."]}}},"ex26_rope_rotation":{"id":"ex26_rope_rotation","edits":{"cz":"Kruhové vlny bojovým lanem ven","eq":["lano","prostor","rope_anchor"],"pos":["Zkontroluj bojové lano, držadla a kotvení určené pro tento úkol podle návodu výrobce. Nech volnou celou dráhu lana. Uchop jeden konec do každé ruky, mírně pokrč kyčle a kolena a ustal postoj; lano netahej do úplného napnutí.","Check the battle rope, handles and an anchor intended for this task according to the manufacturer instructions. Clear the full rope path. Hold one end in each hand, soften hips and knees and establish a stable stance; avoid pulling the rope completely taut."],"foc":["Kruhy rukou směrem ven, které vytvářejí souběžné kruhové vlny.","Outward hand circles producing simultaneous circular rope waves."],"exe":["Oběma rukama opisuj malé kruhy směrem ven, pravou a levou v opačném směru. Vlny veď podél lan ke kotvě a drž plynulý rytmus.","Make small outward circles with both hands, with right and left moving in opposite directions. Send the waves along the ropes toward the anchor with a continuous rhythm."],"wat":["Ruce nekrouží stejným směrem ani nad hlavou. Nenahrazuj kruh záklonem nebo škubáním celým trupem. Zvol velikost, při které se dráhy lan nekříží nekontrolovaně.","The hands do not circle in the same direction or overhead. Avoid replacing circles with backward leaning or whole-trunk jerking. Choose a size that prevents uncontrolled crossing of rope paths."],"pro":["Nejdřív malé pomalé kruhy, potom souvislejší rytmus podle kontroly. Větší kruh není automaticky lepší; konec úseku zvol před rozpadem techniky.","Begin with small slow circles, then develop continuity as control allows. A larger circle is not automatically better; end the interval before technique breaks down."],"equipmentDetail":["Zapisuj sekundy celého pracovního úseku pro obě ruce společně, nikoli počet vln nebo čas každé ruky zvlášť. Původní časy se nemění. Typ lana, rytmus a velikost vln můžeš poznamenat; samotný delší čas neznamená srovnatelně lepší výkon.","Record seconds for the whole work interval with both hands together, not wave counts or separate arm times. Earlier durations remain unchanged. You may note the rope, rhythm and wave size; a longer duration alone is not a comparable performance improvement."]},"taxonomy":{"regions":["shoulders"],"secondaryRegions":["trunk","arms","forearms_hands"],"movements":["rope_waves"],"focus":["conditioning","coordination"],"positions":["standing"],"supports":[],"priority":2,"equipmentRequirements":[["lano"],["prostor"],["rope_anchor"]],"aliases":["Kruhové vlny bojovým lanem","Outward Circular Battle-Rope Waves"]},"policy":{"id":"ex26_rope_rotation","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["lano"],["prostor"],["rope_anchor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"whole-bilateral-rope-work-interval-no-wave-count-or-historical-conversion","selectionPolicy":"explicit-rope-wave-variation","blockedMotionSources":[],"sideNote":["Čas patří celému obouručnímu úseku; opačné směry kruhů nevytvářejí samostatné L/R dávky.","Time covers the whole two-arm interval; opposite circle directions do not create separate L/R doses."],"noAddedWeight":true,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_rope_rotation","atlasId":"ex26_rope_rotation","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"dd332184c5987eba3876bac251e23a1b642cd594653bc398eedacd84ece207bd","thumb":"/expansion-atlas/ex26_rope_rotation-original-256.webp","detail":"/expansion-atlas/ex26_rope_rotation-original-960.webp","inkThumb":"/expansion-atlas/ex26_rope_rotation-ink-256.webp","inkDetail":"/expansion-atlas/ex26_rope_rotation-ink-960.webp","fillThumb":"/expansion-atlas/ex26_rope_rotation-fill-256.webp","fillDetail":"/expansion-atlas/ex26_rope_rotation-fill-960.webp"},"sourceSha256":"dd332184c5987eba3876bac251e23a1b642cd594653bc398eedacd84ece207bd","contourOnly":true,"darkOutline":true},"equipmentLabels":["Bojové lano, odpovídající kotva a volná dráha lana","Battle rope, suitable anchor and clear rope path"],"libraryOrders":{"rope_waves":2},"deliveryProfiles":{"17471f16f06817c6":{"fields":{"id":"ex26_rope_rotation","cz":"Kruhové vlny bojovým lanem ven","en":"Outward Circular Battle-Rope Waves","pat":"tlak","eq":["lano","prostor","rope_anchor"],"measurementType":"DURATION","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Kruhy rukou směrem ven, které vytvářejí souběžné kruhové vlny.","Outward hand circles producing simultaneous circular rope waves."],"startPosition":["Zkontroluj bojové lano, držadla a kotvení určené pro tento úkol podle návodu výrobce. Nech volnou celou dráhu lana. Uchop jeden konec do každé ruky, mírně pokrč kyčle a kolena a ustal postoj; lano netahej do úplného napnutí.","Check the battle rope, handles and an anchor intended for this task according to the manufacturer instructions. Clear the full rope path. Hold one end in each hand, soften hips and knees and establish a stable stance; avoid pulling the rope completely taut."],"execution":["Oběma rukama opisuj malé kruhy směrem ven, pravou a levou v opačném směru. Vlny veď podél lan ke kotvě a drž plynulý rytmus.","Make small outward circles with both hands, with right and left moving in opposite directions. Send the waves along the ropes toward the anchor with a continuous rhythm."],"watchFor":["Ruce nekrouží stejným směrem ani nad hlavou. Nenahrazuj kruh záklonem nebo škubáním celým trupem. Zvol velikost, při které se dráhy lan nekříží nekontrolovaně.","The hands do not circle in the same direction or overhead. Avoid replacing circles with backward leaning or whole-trunk jerking. Choose a size that prevents uncontrolled crossing of rope paths."]},"progression":["Nejdřív malé pomalé kruhy, potom souvislejší rytmus podle kontroly. Větší kruh není automaticky lepší; konec úseku zvol před rozpadem techniky.","Begin with small slow circles, then develop continuity as control allows. A larger circle is not automatically better; end the interval before technique breaks down."]}}},"ex26_burpee_bar":{"id":"ex26_burpee_bar","edits":{"foc":["Kontrolovaný přechod do kliku a zpět do stoje, následovaný bočním přeskokem osy.","A controlled transition into a push-up and back to standing, followed by a lateral jump over the bar."],"pos":["Polož osu na stabilní neklouzavou plochu a zajisti ji proti odkutálení. Zkontroluj volný prostor pro klik, odraz a dopad na obou stranách. Postav se bokem k ose; výška překážky musí odpovídat zvládnutému přeskoku.","Place the bar on a stable non-slip surface and secure it against rolling. Check clearance for the push-up, takeoff and landing on both sides. Stand side-on to the bar; the obstacle height must suit a jump you can control."],"exe":["Polož dlaně na zem, přejdi do vzporu a udělej kontrolovaný klik v rozsahu, který udržíš. Vrať chodidla pod tělo a narovnej se. Přeskoč osu do strany, měkce dopadni a ustal postoj před dalším opakováním.","Place the palms on the floor, move into a plank and perform a controlled push-up within a range you can maintain. Bring the feet under the body and stand. Jump sideways over the bar, absorb the landing and establish control before the next repetition."],"wat":["Ověř stabilitu osy před sérií; samotný výběr vybavení ji nekontroluje. Pokud se osa pohybuje nebo chybí prostor pro dopad, zvol jiný úkol. Sérii ukonči před ztrátou kontroly. Překročení místo přeskoku je změna úkolu, kterou zvol a zapiš před dalším úsekem.","Check bar stability before the set; selecting equipment does not verify it. If the bar moves or landing space is insufficient, choose a different task. End the set before losing control. Stepping over instead of jumping is a change of task: choose and record it before the next interval."],"pro":["Jednotlivé části nejprve nacvič odděleně. Snazší možnost je burpee s odkročením a překročením nízkého značení, zvolená jako upravený úkol. Plynulejší návaznost přidávej ručně; vyšší překážka ani závodní tempo nejsou povinným cílem.","First practise the parts separately. A step-back burpee with a step over a low marker is an easier modified task. Develop continuity deliberately; a higher obstacle or competition pace is not a required goal."],"equipmentDetail":["Osa slouží jako překážka, nezvedá se. Jedno opakování je celý burpee a jeden přeskok na opačnou stranu; cesta tam a zpět jsou dvě opakování. Počítá se celek, ne každá fáze zvlášť. Historické počty, strany ani hmotnosti nepřepočítáváme.","The bar is an obstacle and is not lifted. One repetition is a complete burpee followed by one jump to the opposite side; going across and back is two repetitions. Count the whole task, not each phase. Do not convert historical counts, sides or loads."]},"taxonomy":{"regions":["thighs","chest"],"secondaryRegions":["hips","trunk","shoulders","arms","lower_legs"],"movements":["push_horizontal","jump","landing"],"focus":["conditioning","coordination"],"positions":["standing","high_plank"],"supports":["hand_support"],"priority":2,"equipmentRequirements":[["cinka"],["prostor"]],"aliases":["Burpee s bočním přeskokem osy","Lateral Burpee Over Bar"]},"policy":{"id":"ex26_burpee_bar","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["cinka"],["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-burpee-and-one-bar-crossing-per-rep-no-retrospective-count-conversion","selectionPolicy":"explicit-controlled-pushup-and-lateral-jump-task","blockedMotionSources":[],"noAddedWeight":true,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ex26_burpee_bar","atlasId":"ex26_burpee_bar","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"22e5fb343efe5e1bb34ab5ebc4819eb5ac11bca0131d64993230a3fcd512be66","thumb":"/expansion-atlas/ex26_burpee_bar-audit20261013-original-256.webp","detail":"/expansion-atlas/ex26_burpee_bar-audit20261013-original-960.webp","inkThumb":"/expansion-atlas/ex26_burpee_bar-audit20261013-ink-256.webp","inkDetail":"/expansion-atlas/ex26_burpee_bar-audit20261013-ink-960.webp","fillThumb":"/expansion-atlas/ex26_burpee_bar-audit20261013-fill-256.webp","fillDetail":"/expansion-atlas/ex26_burpee_bar-audit20261013-fill-960.webp"},"sourceSha256":"22e5fb343efe5e1bb34ab5ebc4819eb5ac11bca0131d64993230a3fcd512be66","contourOnly":true,"darkOutline":true},"equipmentLabels":["Osa zajištěná proti odkutálení; volný neklouzavý prostor na obou stranách","Bar secured against rolling; clear non-slip space on both sides"],"libraryOrders":{},"deliveryProfiles":{"11cd0527492ec945":{"fields":{"id":"ex26_burpee_bar","cz":"Burpee s bočním přeskokem osy","en":"Lateral Burpee Over Bar","pat":"prenos","eq":["telo","cinka","prostor"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Kontrolovaný přechod do kliku a zpět do stoje, následovaný bočním přeskokem osy.","A controlled transition into a push-up and back to standing, followed by a lateral jump over the bar."],"startPosition":["Polož osu na stabilní neklouzavou plochu a zajisti ji proti odkutálení. Zkontroluj volný prostor pro klik, odraz a dopad na obou stranách. Postav se bokem k ose; výška překážky musí odpovídat zvládnutému přeskoku.","Place the bar on a stable non-slip surface and secure it against rolling. Check clearance for the push-up, takeoff and landing on both sides. Stand side-on to the bar; the obstacle height must suit a jump you can control."],"execution":["Polož dlaně na zem, přejdi do vzporu a udělej kontrolovaný klik v rozsahu, který udržíš. Vrať chodidla pod tělo a narovnej se. Přeskoč osu do strany, měkce dopadni a ustal postoj před dalším opakováním.","Place the palms on the floor, move into a plank and perform a controlled push-up within a range you can maintain. Bring the feet under the body and stand. Jump sideways over the bar, absorb the landing and establish control before the next repetition."],"watchFor":["Ověř stabilitu osy před sérií; samotný výběr vybavení ji nekontroluje. Pokud se osa pohybuje nebo chybí prostor pro dopad, zvol jiný úkol. Sérii ukonči před ztrátou kontroly. Překročení místo přeskoku je změna úkolu, kterou zvol a zapiš před dalším úsekem.","Check bar stability before the set; selecting equipment does not verify it. If the bar moves or landing space is insufficient, choose a different task. End the set before losing control. Stepping over instead of jumping is a change of task: choose and record it before the next interval."]},"progression":["Jednotlivé části nejprve nacvič odděleně. Snazší možnost je burpee s odkročením a překročením nízkého značení, zvolená jako upravený úkol. Plynulejší návaznost přidávej ručně; vyšší překážka ani závodní tempo nejsou povinným cílem.","First practise the parts separately. A step-back burpee with a step over a low marker is an easier modified task. Develop continuity deliberately; a higher obstacle or competition pace is not a required goal."]}}},"ig27_crab_toe_touch":{"id":"ig27_crab_toe_touch","edits":{"eq":["telo","prostor"],"equipmentDetail":["Volný prostor na pevné neklouzavé podlaze, podložka podle pohodlí. Jeden dosah a návrat je jedno opakování na danou stranu. V novém zadání označ stranu podle zvedané nohy; opačná ruka k ní dosahuje. Dvojice pravá a levá je jedno opakování na každou stranu, ne dvě na obě. Historické L/R ani počty nepřeznačujeme.","Clear space on a firm non-slip floor; a mat is optional for comfort. One reach and return is one repetition on that side. In new prescriptions identify the side by the raised leg; the opposite hand reaches toward it. A right-and-left pair is one repetition per side, not two on each. Historical L/R labels and counts are not relabelled."]},"taxonomy":{"regions":["trunk"],"secondaryRegions":["shoulders","arms","hips"],"movements":["balance","trunk_stability"],"focus":["coordination","balance"],"positions":["reverse_support"],"supports":["hand_support"],"priority":2,"equipmentRequirements":[["prostor"]],"aliases":["Dotek protilehlého chodidla v krabí opoře","Alternating Crab Toe Touch","crab toe tap"]},"policy":{"id":"ig27_crab_toe_touch","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-reach-return-per-recorded-side-no-historical-side-relabel","selectionPolicy":"explicit-bodyweight-coordination-task","blockedMotionSources":[],"sideMeaning":["Zvedaná noha","Raised leg"],"sideNote":["Pro nový zápis L/R označuje zvedanou nohu; dotýká se jí opačná ruka. Jeden dosah a návrat je jedno opakování na zaznamenanou stranu. Význam platí pro nové zadání. Dřívější L/R ani neurčenou stranu nepřeznačujeme.","For a new record L/R identifies the raised leg, reached by the opposite hand. One reach and return is one repetition on the recorded side. This meaning applies to a new prescription. Earlier L/R and unspecified sides are not relabelled."],"noAddedWeight":true,"allowCopyCompletedAcrossSides":false,"preserveSide":true},"art":{"appId":"ig27_crab_toe_touch","atlasId":"ig27_crab_toe_touch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5fb3d8949d1167d886f7a9feb67d027a18635797ce029fda503fd0c5019d8d01","thumb":"/expansion-atlas/ig27_crab_toe_touch-original-256.webp","detail":"/expansion-atlas/ig27_crab_toe_touch-original-960.webp","inkThumb":"/expansion-atlas/ig27_crab_toe_touch-ink-256.webp","inkDetail":"/expansion-atlas/ig27_crab_toe_touch-ink-960.webp","fillThumb":"/expansion-atlas/ig27_crab_toe_touch-fill-256.webp","fillDetail":"/expansion-atlas/ig27_crab_toe_touch-fill-960.webp"},"sourceSha256":"5fb3d8949d1167d886f7a9feb67d027a18635797ce029fda503fd0c5019d8d01","contourOnly":true,"darkOutline":true},"equipmentLabels":["Pevná neklouzavá podlaha a prostor; podložka volitelně","Firm non-slip floor and space; optional mat"],"libraryOrders":{},"deliveryProfiles":{"c0d65d08817b836a":{"fields":{"id":"ig27_crab_toe_touch","cz":"Dotek protilehlého chodidla v krabí opoře","en":"Alternating Crab Toe Touch","pat":"stred","eq":["telo","prostor"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Jedna dlaň a opačné chodidlo nesou váhu, volné končetiny se pomalu setkají.","One palm and the opposite foot carry the load as the free limbs meet slowly."],"startPosition":["Sedni s pokrčenými koleny a celými chodidly na zemi. Dlaně polož za pánev, prsty v pohodlném směru. Zvedni pánev jen kousek nad zem.","Sit with bent knees and feet flat. Place the palms behind the pelvis, fingers in a comfortable direction. Lift the pelvis just clear of the floor."],"execution":["Přenes oporu na pravou dlaň a levé chodidlo. Pravou nohu zvedni a levou rukou dosáhni k jejímu chodidlu. Obě končetiny vrať a vystřídej strany. Jeden dosah a návrat jsou jedno opakování na danou stranu.","Balance on the right palm and left foot. Lift the right leg and reach the left hand toward that foot. Replace both limbs and switch sides. One reach and return count as one repetition on that side."],"watchFor":["Dosahuj pomalu, bez švihu nohou a bez propadnutí do opěrného ramene. Dotek není podmínkou. Při nepříjemném tlaku v zápěstí nebo rameni polož pánev a zvol jinou oporu.","Reach slowly without kicking or sinking into the supporting shoulder. Contact is optional. If the wrist or shoulder feels uncomfortable, lower the pelvis and choose another support exercise."]},"progression":["Lehčí: nejdřív udrž nízkou oporu na čtyřech bodech, potom sahaj jen ke kolenu. Těžší: narovnej zvedanou nohu více a krátce zastav v dosahu; rychlost nezvyšuj na úkor rovnováhy.","Easier: first maintain the low four-point support, then reach only to the knee. Harder: straighten the lifted leg farther and briefly pause at the reach without sacrificing balance for speed."]}}},"ig29_prone_w_to_forearm_plank":{"id":"ig29_prone_w_to_forearm_plank","edits":{"eq":["telo","prostor"],"exe":["Lehce odlehči hrudník, paže a nohy, pánev zůstává na podložce. Pomalu vše polož. Lokty nastav přímo pod ramena, předloktí rovnoběžně, opři špičky a zpevni trup. Odtlačením předloktí zvedni tělo do prkna, krátce zastav a kontrolovaně se polož. Na zemi vrať paže do W. To je jeden celý cyklus. Počet a případnou délku zastavení zvol podle konkrétního zadání a zachované kontroly.","Gently lift the chest, arms and legs while the pelvis stays on the mat. Lower everything slowly. Place the elbows directly under the shoulders with forearms parallel, tuck the toes and brace the trunk. Press through the forearms to lift into a plank, pause briefly and lower with control. On the floor, return the arms to W. This is one complete cycle. Choose the count and any pause duration for the individual prescription while maintaining control."],"equipmentDetail":["Pevná neklouzavá podlaha a volný prostor pro celé tělo; podložka může zpříjemnit oporu. Zapisuj celé cykly W–položení–prkno–položení, ne každou fázi zvlášť. Zastavení v prkně nemění počet na sekundy a historické dávky nepřepočítáváme.","A firm non-slip floor with clearance for the whole body; a mat may make contact more comfortable. Record complete W–lower–plank–lower cycles, not each phase separately. A plank pause does not change the count into seconds, and historical doses are not converted."],"source":{"author":"Leo Moves","document":"Four-movement bodyweight sequence: prone back lift and forearm-plank transition","url":"https://www.instagram.com/leo.moves/reel/DcG2OkupHcn/","scope":"Exact component sequence was documented in the saved demonstration. The low W lift, deliberate return to the floor and knee-supported option are our coaching adaptation. Individual dosing is selected in the workout; no treatment or universal beginner claim.","instagram":"https://www.instagram.com/leo.moves/reel/DcG2OkupHcn/","instagramUrls":["https://www.instagram.com/leo.moves/reel/DcG2OkupHcn/"],"technicalSources":[{"author":"ACE","url":"https://www.acefitness.org/resources/everyone/exercise-library/9/supermans/","scope":"Small prone limb lift and aligned neck; component technique only, not endorsement of this W-to-plank sequence."},{"author":"ACE","url":"https://www.acefitness.org/resources/everyone/exercise-library/32/front-plank/","scope":"Forearm support, controlled whole-body lift and lowering; component technique only."},{"author":"Shepherd Center","url":"https://myshepherdconnection.org/living-with-injury/exercise-wellness/home-exercises/","scope":"Modified prone-to-plank with knees supported corroborates the regression; no rehabilitation claim transferred to the card."}]}},"taxonomy":{"regions":["trunk","back"],"secondaryRegions":["hips","shoulders"],"movements":["trunk_movement","trunk_stability"],"focus":["strength","coordination"],"positions":["prone","forearm_plank"],"supports":["forearm_support"],"priority":2,"equipmentRequirements":[["prostor"]],"aliases":["Záklon na břiše s pažemi v poloze W a přechod do prkna","Prone W Lift to Forearm Plank","W lift to plank"]},"policy":{"id":"ig29_prone_w_to_forearm_plank","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["prostor"]],"unknown":false,"explicitTarget":true,"requiresCoach":false,"manualProgression":true,"manualWarmup":true,"warmupPolicy":"NONE","allowEstimatedMax":false,"allowComparableRecords":false,"allowAddedWeightRecord":false,"allowAutomaticProgression":false,"secondaryLoad":"none","recordingPolicy":"one-complete-prone-W-plank-cycle-not-phase-count-or-seconds","selectionPolicy":"explicit-bodyweight-coordination-task","blockedMotionSources":[],"noAddedWeight":true,"allowCopyCompletedAcrossSides":false},"art":{"appId":"ig29_prone_w_to_forearm_plank","atlasId":"ig29_prone_w_to_forearm_plank","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"7dbee1d6d2fb58d86719464e7aeb8af9a437edb7c762f9cca5216abd5046079d","thumb":"/expansion-atlas/ig29_prone_w_to_forearm_plank-original-256.webp","detail":"/expansion-atlas/ig29_prone_w_to_forearm_plank-original-960.webp","inkThumb":"/expansion-atlas/ig29_prone_w_to_forearm_plank-ink-256.webp","inkDetail":"/expansion-atlas/ig29_prone_w_to_forearm_plank-ink-960.webp","fillThumb":"/expansion-atlas/ig29_prone_w_to_forearm_plank-fill-256.webp","fillDetail":"/expansion-atlas/ig29_prone_w_to_forearm_plank-fill-960.webp"},"sourceSha256":"7dbee1d6d2fb58d86719464e7aeb8af9a437edb7c762f9cca5216abd5046079d","contourOnly":true,"darkOutline":true},"equipmentLabels":["Pevná neklouzavá podlaha a prostor; podložka volitelně","Firm non-slip floor and space; optional mat"],"libraryOrders":{},"deliveryProfiles":{"018f1e05006a8317":{"fields":{"id":"ig29_prone_w_to_forearm_plank","cz":"Záklon na břiše s pažemi v poloze W a přechod do prkna","en":"Prone W Lift to Forearm Plank","pat":"stred","eq":["telo","prostor"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Malý zdvih, položení, zpevnění a plynulé prkno.","Small lift, set down, brace and rise smoothly into plank."],"startPosition":["Lehni na břicho, nohy přibližně na šířku boků. Pokrč lokty a polož paže do pohodlného W vedle hlavy. Čelo drž blízko podložky a pohled dolů.","Lie face down with legs roughly hip-width apart. Bend the elbows into a comfortable W beside the head. Keep the forehead close to the mat and look down."],"execution":["Lehce odlehči hrudník, paže a nohy, pánev zůstává na podložce. Pomalu vše polož. Lokty nastav přímo pod ramena, předloktí rovnoběžně, opři špičky a zpevni trup. Odtlačením předloktí zvedni tělo do prkna, krátce zastav a kontrolovaně se polož. Na zemi vrať paže do W. To je jeden celý cyklus. Počet a případnou délku zastavení zvol podle konkrétního zadání a zachované kontroly.","Gently lift the chest, arms and legs while the pelvis stays on the mat. Lower everything slowly. Place the elbows directly under the shoulders with forearms parallel, tuck the toes and brace the trunk. Press through the forearms to lift into a plank, pause briefly and lower with control. On the floor, return the arms to W. This is one complete cycle. Choose the count and any pause duration for the individual prescription while maintaining control."],"watchFor":["V záklonu stačí malý zdvih, nezakláněj hlavu a netlač bedra do krajní polohy. Do prkna se nezvedej vlnou přes prohnutá záda. Lokty drž pod rameny, pánev bez propadu a dýchej. Pokud ztrácíš kontrolu nad přechodem, procvič obě polohy odděleně.","Use a small prone lift without throwing the head back or forcing the lower back to end range. Do not ripple into the plank through an arched back. Keep elbows under shoulders, hips from sagging and breathing steady. Practise the two positions separately if you lose control of the transition."]},"progression":["Lehčí: procvič obě polohy odděleně, v záklonu ponech nohy na zemi a při zvedání do prkna opři kolena. Těžší: zpomal položení těla nebo mírně prodluž klidnou výdrž v prkně. Nezvyšuj záklon ani rychlost přechodu.","Easier: practise the positions separately, keep the legs grounded during the prone lift and support the knees when rising into the plank. Harder: lower more slowly or slightly extend the steady plank hold. Do not increase backbend depth or transition speed."]}}}}};
for(const path of packed.undefinedPaths){let o=packed.value;for(const key of path.slice(0,-1))o=o[key];o[path.at(-1)]=undefined;}
